'use strict';
(function(){
 const state=document.getElementById('state'),note=document.getElementById('state-note'),panel=document.getElementById('state-resources'),heading=document.getElementById('state-heading'),intro=document.getElementById('state-intro'),draft=document.getElementById('request-template'),download=document.getElementById('download-template'),print=document.getElementById('print-template');
 if(!state||!note||!panel||!heading||!intro||!draft||!download||!print)return;
 const rcfp='https://www.rcfp.org/open-government-guide/';
 const guideLink=document.getElementById('guide-link');
 // Preliminary official-source research only. Not an attorney-reviewed legal verification.
 const independentlyAuditedStates=new Set(['Vermont']);
 const enhancedReviewStates=new Set(['Louisiana','Kentucky','Iowa','Kansas','Illinois','Indiana','Hawaii','Idaho','Florida','Georgia','Connecticut','Delaware','Arkansas','Colorado','Alabama','Alaska','Arizona','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming']);
 const verified={Utah:{law:'Utah Government Records Access and Management Act (GRAMA), Utah Code §§ 63G-2-201 through 63G-2-404',summary:'SOURCE REVIEW 2026-11-22 (Utah Legislature GRAMA chapter and Utah State Archives FAQ); substantive review, NOT an exhaustive certification. ELIGIBILITY: Any person may request public records; no Utah residency condition is stated in the general GRAMA request rule. REQUEST: Under § 63G-2-204(1), submit a written request to the entity retaining the records, identifying the records with reasonable specificity and giving name, mailing address, daytime telephone number and email when applicable; use the Utah Open Records Portal, email, mail, fax or in person as accepted by the agency. RESPONSE: Under § 63G-2-204, ordinarily within 10 business days the agency must produce, deny, identify another custodian if known, or give a qualifying extraordinary-circumstances notice with an availability date. Five business days applies when expedited public-benefit processing is demonstrated; this is not a blanket five-day right. Extraordinary circumstances can extend actual production. FEES: § 63G-2-203 generally allows reasonable actual-cost charges, limited staff-time charges and potential advance payment; public-benefit, subject-of-record and qualifying indigent legal-rights grounds support discretionary fee relief. Confirm agency-specific schedules before quoting an amount. EXEMPTIONS: §§ 63G-2-301, 302, 304 and 305 distinguish public, private, controlled and protected records. Initial contact reports and chronological police logs have specific public-record provisions; investigative, privacy, victim and safety protections can require withholding or redaction. Do not presume all police personnel files, disciplinary investigations, body-camera footage or 911 recordings are either public or categorically exempt; evaluate record-specific statutes. DENIAL/APPEALS: § 63G-2-205 requires denial information; generally appeal to the agency chief administrative officer within 30 days, whose ordinary decision period is 10 business days under § 63G-2-401. Further appeal to the Government Records Office director generally has a 30-day deadline under § 63G-2-403, subject to specific exceptions and mediation rules. Judicial review under § 63G-2-404 may have a separate 30-day limit. OPEN CHECKS: verify exact current section versions and amendments, fee schedule for each agency, officer discipline, body-camera/911 special provisions, deemed-denial exceptions, and judicial tolling. Do not treat these summary periods as legal advice.',links:[['Utah Legislature — GRAMA full chapter (current compilation)','https://le.utah.gov/xcode/Title63G/Chapter2/C63G-2_1800010118000101.pdf'],['Utah Archives — official GRAMA request and appeals FAQ','https://archives.utah.gov/transparency-services/government-records-access/faq/'],['Utah Open Records Portal','https://openrecords.utah.gov/'],['Utah Legislature — § 63G-2-204 response statute','https://le.utah.gov/xcode/title63g/chapter2/C63G-2-S204_2023050320230503.pdf']]},Vermont:{law:'Vermont Public Records Act, 1 V.S.A. §§ 315–320',summary:"SOURCE REVIEW 2026-11-23 (2026-session Vermont Legislature §§ 316-319; Secretary of State; Vermont State Police). NOT EXHAUSTIVELY CERTIFIED. ELIGIBILITY: Any person may request public records; no residency requirement in § 316(a). REQUEST: Direct a reasonably specific inspection or copy request to the records custodian; Vermont State Police accepts online or written requests and publishes agency-specific procedures. RESPONSE: § 318(a)-(b) requires prompt production, normally within 3 business days, not merely acknowledgment. Active-use/storage records require written certification and an appointment within one calendar week. Unusual circumstances allow written notice with reasons and expected determination date, no later than 10 business days from receipt; statutory noncompliance is deemed denial. DENIAL: Written notice must identify withheld records, statutory grounds, supporting facts, responsible officials and appeal rights; § 318(e) requires segregable nonexempt portions and explanation of redactions. FEES: § 316(b)-(e) permits actual copying/transmission costs and qualifying staff time where directly involved work exceeds 30 minutes or agreed special creation/format applies; request an estimate. Ordinary inspection is distinct from charged copies. VSP separately publishes statutory police-record charges including $20 reports and $45 video/audio, subject to applicable law. WAIVERS: No general mandatory public-interest waiver was verified; check agency-specific policy and statute. EXEMPTIONS: § 317(c)(5) criminal-investigation exemption requires enumerated harms, not a blanket police-record exclusion; records of law-enforcement management and initial arrests/charges have express public-access treatment, subject to juvenile protections. Salaries and benefits are expressly nonexempt under § 317(b); personnel/privacy/confidentiality provisions require record-specific analysis. Body-camera, 911 and disciplinary files require individual exemption checks. APPEALS: § 318(c) permits agency-head appeal; written decision ordinarily due within 5 business days. § 319 authorizes de novo Civil Division Superior Court enforcement and fee-shifting rules. No universal judicial filing limitation was verified in §§ 318-319; confirm procedural accrual and case law before filing. OPEN CHECKS: 2026 enactment effective-date nuances; specific 911/BWC/discipline confidentiality; fee waiver rules and current Secretary of State charge schedule; judicial limitations and recent decisions. Legislature labels its online compilation unofficial.",links:[["Vermont Legislature — § 316 access and fees","https://legislature.vermont.gov/statutes/section/01/005/00316"],["Vermont Legislature — § 317 exemptions and police records","https://legislature.vermont.gov/statutes/section/01/005/00317"],["Vermont Legislature — § 318 deadlines, denial and appeal","https://legislature.vermont.gov/statutes/section/01/005/00318"],["Vermont Legislature — § 319 enforcement","https://legislature.vermont.gov/statutes/section/01/005/00319"],["Vermont Secretary of State — public records guidance","https://sos.vermont.gov/municipal-division/public-records"],["Vermont State Police — requests and fees","https://vsp.vermont.gov/public/recordrequests"]]},Virginia:{law:"Virginia Freedom of Information Act, Va. Code § 2.2-3700 et seq.",summary:"SOURCE REVIEW 2026-11-23 (current Virginia Code §§ 2.2-3704, 3704.01, 3705.1, 3706, 3706.1, 3713 and 2026 Virginia FOIA Advisory Council guidance); substantive official-source review, NOT exhaustive certification. ELIGIBILITY: § 2.2-3704(A) grants access to Virginia citizens and qualifying newspapers, magazines, radio and television representatives; a custodian may request name and legal address. REQUEST: Describe existing records with reasonable specificity to the responsible custodian; no citation to FOIA is required. Oral or written requests may qualify, though writing creates a useful record. RESPONSE VERSUS PRODUCTION: Within five working days the agency must provide records or issue a specified written withholding, partial withholding, no-records, or impracticability response. Timely written impracticability notice permits seven additional working days; requests for criminal investigative files under § 2.2-3706.1 may instead receive 60 additional working days. Extraordinary volume may support a court extension after reasonable efforts to agree with the requester. Silence is a deemed denial; do not treat five days as a universal production deadline. FEES: § 2.2-3704(F)-(I) limits ordinary search, access and copying charges to actual cost; no general public-interest fee waiver is established here. Agency must notify of potential charges and offer a cost estimate; if requested, the estimate pauses the response clock until requester responds, and no response within 30 days withdraws the request. Estimated charges above $200 permit a deposit, which also tolls the deadline. EXEMPTIONS: § 2.2-3705.1 protects identifiable personnel information subject to exceptions including subject access and certain employment disclosures; § 2.2-3706(B)(9) covers law-enforcement applicant background and employee wrongdoing administrative investigations. §§ 2.2-3706 and 3706.1 distinguish mandatory adult booking/charge and felony incident information from discretionary criminal investigative files, with additional rights for qualifying victims and others after investigations end. 911 calls are subject to FOIA, with applicable privacy redactions; body-camera recordings require record-specific review of these and other restrictions. § 2.2-3704.01 requires segregating nonexempt information. DENIAL/REMEDIES: Written withholding must cite the specific exemption for each category and describe withheld material; nonresponse is denial. § 2.2-3713 provides mandamus/injunction in the proper court with affidavit showing good cause, normally at least three working days advance notice to respondent, and an expedited hearing framework. This is not an administrative appeal with a fixed 30-day deadline. Confirm any applicable limitation period with counsel. OPEN CHECKS: 2026 amendments/effective dates, body-camera-specific rules, detailed salary/disciplinary disclosure exceptions, individual agency fee schedules, and applicable court filing limitations/case law.",links:[["Virginia Legislature — § 2.2-3704 requests, deadlines and fees","https://law.lis.virginia.gov/vacode/title2.2/chapter37/section2.2-3704/"],["Virginia Legislature — § 2.2-3704.01 mandatory redaction","https://law.lis.virginia.gov/vacode/title2.2/chapter37/section2.2-3704.01/"],["Virginia Legislature — § 2.2-3705.1 personnel exemptions","https://law.lis.virginia.gov/vacode/title2.2/chapter37/section2.2-3705.1/"],["Virginia Legislature — § 2.2-3706 police and 911 records","https://law.lis.virginia.gov/vacode/title2.2/chapter37/section2.2-3706/"],["Virginia Legislature — § 2.2-3706.1 criminal investigative files","https://law.lis.virginia.gov/vacode/title2.2/chapter37/section2.2-3706.1/"],["Virginia Legislature — § 2.2-3713 judicial enforcement","https://law.lis.virginia.gov/vacode/title2.2/chapter37/section2.2-3713/"],["Virginia FOIA Advisory Council — 2026 access guide","https://foiacouncil.dls.virginia.gov/ref/Access%20to%20Public%20Records%202026%20DOCUMENT.html"]]},Washington:{law:'Washington Public Records Act, RCW Chapter 42.56',summary:'ELIGIBILITY/SUBMISSION: Anyone may request identifiable, nonexempt public records from the appropriate agency. RESPONSE: RCW 42.56.520 requires an initial response within five business days, which may provide records, a link, an estimated timeframe, a clarification request, or a denial; it is not a universal five-day production deadline. FEES/EXEMPTIONS: Copying fees, personal privacy, personnel and investigative exemptions may apply. REVIEW: Denials require written reasons; judicial review under RCW 42.56.550 has a one-year filing provision measured from the agency claim of exemption or last installment production. Verify accrual and other procedural rules for a particular dispute.',links:[['Washington Legislature — response requirements','https://app.leg.wa.gov/Rcw/default.aspx?cite=42.56.520'],['Washington Legislature — judicial review','https://app.leg.wa.gov/RCW/default.aspx?Cite=42.56.550'],['Washington Legislature — full public records chapter','https://app.leg.wa.gov/RCW/default.aspx?cite=42.56&full=true']]},'West Virginia':{law:'West Virginia Freedom of Information Act, W. Va. Code § 29B-1-1 et seq.',summary:'ELIGIBILITY/SUBMISSION: Every person may request qualifying public records directly from the custodian; describe the records with reasonable specificity. RESPONSE: § 29B-1-3 generally requires the custodian, as soon as practicable and within five days excluding weekends and legal holidays, to furnish copies, offer inspection, or deny in writing with reasons. FEES/EXEMPTIONS: Actual reproduction costs may be charged, but search/retrieval labor charges are barred under § 29B-1-3(e); statutory privacy and other exemptions apply. REVIEW: A denial may be challenged for injunctive or declaratory relief in circuit court in the county where records are kept. Preserve the denial and seek advice about timing.',links:[['West Virginia Legislature — § 29B-1-3','https://code.wvlegislature.gov/29B-1-3/'],['West Virginia Legislature — full FOIA chapter','https://code.wvlegislature.gov/pdf/29B-1/']]},Wisconsin:{law:'Wisconsin Public Records Law, Wis. Stat. §§ 19.31–19.39',summary:'ELIGIBILITY/SUBMISSION: Any requester may ask the records authority for identifiable records; no special form is generally required. RESPONSE: § 19.35(4)(a) requires a response as soon as practicable and without delay, NOT a fixed number of days. FEES/EXEMPTIONS: Actual permissible copying charges apply; locating fees generally require at least $50 in location costs and advance payment may be required for charges above $5. Wisconsin also applies statutory exceptions and a public-interest balancing test. REVIEW: A requester can seek mandamus in court or ask the district attorney or Attorney General to pursue enforcement under § 19.37; those offices are not required to take every case.',links:[['Wisconsin DOJ — public records FAQ and enforcement','https://www.wisdoj.gov/Pages/AboutUs/public-records.aspx'],['Wisconsin DOJ — compliance guide','https://www.wisdoj.gov/Open%20Government/PRL_guide.pdf']]},Wyoming:{law:'Wyoming Public Records Act, Wyo. Stat. §§ 16-4-201–205',summary:'ELIGIBILITY/SUBMISSION: Any person may request public records from the designated public-records person of the governmental entity holding them. RESPONSE: § 16-4-202 provides for immediate release of readily available records when practicable; certain notices must be sent within seven business days; generally records must be released within 30 calendar days unless good cause prevents it. FEES/EXEMPTIONS: Reasonable electronic production costs, security and confidential-record exceptions may apply. REVIEW: The Governor’s Public Records Ombudsman can mediate and address certain disputes but does not give binding legal advice; district court remedies also exist. Confirm current law and any good-cause extension before taking action.',links:[['Wyoming Governor — Public Records Ombudsman','https://governor.wyo.gov/contact/public-records-ombudsman'],['Wyoming RCFP — statute and enforcement overview','https://www.rcfp.org/open-government-guide/wyoming/']]},'South Dakota':{law:'South Dakota Codified Laws ch. 1-27 (codification effective Sept. 3, 2026)',summary:'SOURCE REVIEW CHECKED 2026-11-22 (official SD Legislature codified chapter and Attorney General guidance; not exhaustive legal certification). ELIGIBILITY: § 1-27-1 allows South Dakota citizens and other persons interested in examination of public records to inspect and obtain copies during ordinary business hours; do not impose an unsupported residency-only restriction. REQUEST: Under § 1-27-35 begin informally with the records custodian; if denied in whole or part, submit a written request to the public record officer under § 1-27-37. The Attorney General requires hard-copy mailed formal requests for its own records; check each agency method. RESPONSE: The public record officer has TEN BUSINESS DAYS after receipt of the formal written request to provide records, deny with written reasons, or acknowledge with a reasonable further-time estimate; this is not an unconditional production deadline. Failure to respond or to honor an estimate without a revised estimate can be deemed denial. A clarification request unanswered in writing within ten business days can cause withdrawal. FEES: §§ 1-27-35–36 allow actual transmission/reproduction costs and staff-time costs for informal requests requiring over one hour; requests likely exceeding $50 require an advance estimate and written acceptance; public-interest reduction or waiver is discretionary. EXEMPTIONS: § 1-27-1.5 protects qualifying personnel information (but not salaries, routine directory information, or public employment contracts/compensation documents), investigative and law-enforcement records, safety/security information, medical information and other categories. The law-enforcement provision contains a 911 recording/transcript public-interest balancing exception; do not imply all 911 recordings are categorically confidential. § 1-27-1.10 permits redaction and treats redaction as partial denial; § 23-5-11 may independently restrict criminal justice information. REVIEW: Under § 1-27-38, a requester may generally start a civil action by summons or file written notice of review with the Office of Hearing Examiners within NINETY DAYS of denial, including qualifying fee/time disputes; the administrative notice requires registered or certified mail and specified attachments. Subsequent circuit-court appeal follows § 1-27-41 and chapter 1-26. UNRESOLVED: verify specific body-camera rules, 2026 HB 1092 effective/codification details, agency copying rates, 911 case law, and deadlines for later administrative appeals before relying on this profile.',links:[['South Dakota Legislature — current chapter 1-27','https://www.sdlegislature.gov/api/Statutes/1-27.html'],['SDCL § 1-27-1 — eligibility','https://sdlegislature.gov/Statutes/1-27-1'],['SDCL § 1-27-35 — informal requests and costs','https://sdlegislature.gov/Statutes/1-27-35'],['SDCL § 1-27-36 — estimate and fee waiver','https://sdlegislature.gov/Statutes/1-27-36'],['SDCL § 1-27-37 — written request and response','https://sdlegislature.gov/Statutes/1-27-37'],['SDCL § 1-27-38 — 90-day review','https://sdlegislature.gov/Statutes/1-27-38'],['SDCL § 1-27-1.5 — exemptions','https://sdlegislature.gov/Statutes/1-27-1.5'],['South Dakota Attorney General — public records','https://atg.sd.gov/legal/opengovernment/publicrecords.aspx'],['2026 HB 1092 — enrolled legislative text (check final effect)','https://sdlegislature.gov/Session/Bill/26637/305664']]},Tennessee:{law:'Tennessee Public Records Act, Tenn. Code Ann. §§ 10-7-501 et seq.',summary:"SOURCE-REVIEWED 2026-11-22 against Tennessee Comptroller Office of Open Records Counsel FAQ, official fee schedule and 2025 codified §10-7-503 text (secondary republication cross-check); not exhaustively certified. ELIGIBILITY: TPRA statutory access right is for Tennessee citizens; agencies may voluntarily serve noncitizens and may request permitted residency identification. REQUEST: Direct sufficiently specific request to agency public-records request coordinator/custodian; inspection requests generally cannot be required in writing or charged; copies may require written request or prescribed form. RESPONSE: Prompt access where practicable; otherwise within SEVEN BUSINESS DAYS custodian must produce, deny in writing with legal basis, or give written reasonable production estimate. Seven days is not a universal production deadline; failure to respond as required is deemed denial. FEES: Copies may carry reasonable charges after an estimate; Comptroller schedule ordinarily 15 cents per standard black-white page, 50 cents per color page, and labor after first hour; charges may be waived/reduced under adopted agency policy, not a universal statutory waiver. EXEMPTIONS: §10-7-504 and other law protect specified confidential, investigative, victim, security and private information; segregable nonconfidential portions should be redacted and released under §10-7-503(a)(5). LAW ENFORCEMENT PERSONNEL: §10-7-503(c) generally opens officer personnel records for inspection subject to §10-7-504(g) and other confidentiality; inspection requires additional identifying details and officer notice within three days. Do not claim all officer discipline is categorically confidential. DENIAL/REVIEW: Seek written grounds; Comptroller Open Records Counsel offers information and dispute assistance, but does not replace judicial remedy; §10-7-505 provides circuit/chancery court petition, with case-specific procedural/limitations questions to verify. UNRESOLVED: confirm post-2025 amendments and 2026 effective dates, specific body-camera/911/criminal-investigation exceptions, §10-7-504(g) scope, precise court limitation and appeal periods, and agency-specific charges. No exhaustive certification.",links:[["Tennessee Comptroller — TPRA FAQ","https://comptroller.tn.gov/office-functions/open-records-counsel/open-meetings/frequently-asked-questions/tennessee-public-records-act-faqs.html"],["Tennessee Comptroller — official reasonable charges schedule","https://www.comptroller.tn.gov/content/dam/cot/orc/documents/oorc/policies-and-guidelines/ScheduleofReasonableCharges.pdf"],["Tennessee Comptroller — policies, forms and mediation","https://comptroller.tn.gov/office-functions/open-records-counsel/office-of-open-records-counsel/policies---guidelines.html"],["Tennessee §10-7-503 — 2025 code text (secondary republication)","https://law.justia.com/codes/tennessee/title-10/chapter-7/part-5/section-10-7-503/"]]},Texas:{law:'Texas Public Information Act (TPIA), Texas Government Code Chapter 552',summary:'SOURCE-REVIEWED 2026-11-22: Texas Legislature Chapter 552 and Texas Attorney General 2026 handbook, requester guidance, fee guidance, 2025 legislative update and ruling procedures. NOT EXHAUSTIVELY CERTIFIED. ELIGIBILITY: Any person may request existing public information; no general Texas residency requirement. The TPIA generally covers governmental bodies, not judicial records. SUBMISSION: Send a written request to the public information officer or designee by U.S. mail, email, hand delivery or an agency-approved method under §552.234; use the agency-designated address and retain receipt evidence. A request does not require creation of new information or answers to questions. RESPONSE: §552.221 requires prompt production, not a universal ten-business-day production deadline. If records cannot be produced within ten business days, the agency generally must give written notice and a reasonable availability date. Effective for requests received on/after 2025-09-01, §552.221(f)-(g) requires written notice within ten business days if no responsive information exists or withholding relies on a qualifying previous determination; identify that determination. WITHHOLDING: §552.301 ordinarily requires the governmental body, not the requester, to seek an Attorney General decision and identify exceptions within ten business days, with additional submissions generally due within fifteen business days. Some information may be withheld under statutes or valid previous determinations without a fresh ruling. FEES: §§552.261-552.274 and Attorney General cost rules control copying, labor and estimates; ask for an itemized estimate, examine available inspection options, and review §552.267 waiver/reduction provisions and overcharge complaints. Do not assume all searches or copies are free. EXEMPTIONS: §§552.101, 552.102, 552.108, 552.117 and other provisions protect specified confidential information, personnel privacy, law-enforcement and prosecution interests; no categorical rule that every police incident or disciplinary record is secret. §552.108(c) preserves access to basic information about arrested persons, arrests and crimes, subject to other confidentiality laws. Body-worn-camera footage additionally implicates Occupations Code Chapter 1701 and other record-specific laws; 911 recordings, victims and juvenile records need separate review. DENIAL/REVIEW: Ask for the statutory withholding ground and any OAG ruling number. Requesters may complain to the OAG or appropriate prosecutor and seek mandamus/injunctive relief under §§552.321 and 552.3215 where applicable. Under §552.306 an agency generally must act as soon as practicable and no later than 30 days after a ruling; this is not a universal requester court-filing deadline. 2025 HB4219 added §552.328 complaint measures for failure to comply with §552.221. UNRESOLVED: Specific body-camera/911 access rules, personnel discipline case law, precise cost schedule and thresholds, agency-specific exceptions, 2026 changes and case-specific judicial limitations; verify before relying on the guide.',links:[['Texas Legislature — current Government Code Chapter 552','https://statutes.capitol.texas.gov/Docs/GV/htm/GV.552.htm'],['Texas Attorney General — 2026 PIA Handbook','https://www.texasattorneygeneral.gov/sites/default/files/files/divisions/open-government/PIA-Handbook-2026.pdf'],['Texas Attorney General — requesting public information','https://www.texasattorneygeneral.gov/open-government/members-public/how-request-public-information'],['Texas Attorney General — 2025 legislative changes','https://www.texasattorneygeneral.gov/open-government/governmental-bodies/2025-texas-legislative-session-update'],['Texas Attorney General — charges and cost complaints','https://www.texasattorneygeneral.gov/open-government/governmental-bodies/charges-public-information'],['Texas Attorney General — ruling questions and judicial remedies','https://www.texasattorneygeneral.gov/open-government/governmental-bodies/previous-attorney-general-decisions-and-rulings/open-records-letter-ruling/questions-regarding-open-records-letter-rulings']]},Oregon:{law:'Oregon Public Records Law, ORS 192.311–192.478 (2025 edition)',summary:'REVIEWED 2026-11-22 against Oregon Legislature 2025 ORS Chapter 192 and official agency guidance. ELIGIBILITY: Every person may inspect nonexempt public records under ORS 192.314; no general residency restriction. REQUEST: Identify records, dates and format in a written request to the public body designated contact under ORS 192.324(7). RESPONSE: ORS 192.324 generally requires acknowledgment or completion within five business days after receipt by designated contact. ORS 192.329 generally requires completion OR a written processing update with a reasonable estimated date within ten business days after the acknowledgment deadline. Neither is an unconditional final-production deadline. Statutory impracticability exceptions and fee or clarification pauses apply; completion must be as soon as practicable without unreasonable delay. FEES: ORS 192.324 permits actual-cost-based charges and public-interest waivers/reductions; request a written estimate and the agency fee policy. ORS 192.329 provides 60-day closure rules for certain unpaid fees and unanswered clarification requests. EXEMPTIONS: ORS 192.345 and 192.355 and other statutes protect specified investigative, personal, personnel, safety and privileged information; redact and release segregable nonexempt portions under ORS 192.338. Police reports, discipline, body-camera footage and 911 recordings require record-specific analysis, not blanket classification. DENIAL AND REVIEW: Request written statutory grounds. State-agency denials generally go to the Attorney General under ORS 192.411, local denials to the district attorney under ORS 192.415, with elected-official exceptions under ORS 192.427. ORS 192.411 generally sets seven days for AG petition decision and distinct agency compliance or litigation steps after disclosure orders, not a blanket requester appeal cutoff. Circuit-court remedies under ORS 192.431; verify case-specific filing limits. UNRESOLVED: 2026 amendments/effective dates, body-camera and 911 special statutes, police disciplinary confidentiality, agency fee differences, elected-official appeal routes and court limitation periods. Not exhaustively certified.',links:[['Oregon Legislature — 2025 ORS Chapter 192','https://www.oregonlegislature.gov/bills_laws/ors/ors192.html'],['Oregon Legislature — public records requests','https://www.oregonlegislature.gov/citizen_engagement/Pages/Public-Records.aspx'],['Oregon State Police — public records','https://www.oregon.gov/osp/programs/Pages/Public-Records-Requests.aspx'],['Oregon Governor — fees and waivers','https://www.oregon.gov/gov/pages/public-records-requests.aspx']]},Pennsylvania:{law:'Pennsylvania Right-to-Know Law, 65 P.S. §§ 67.101–67.3104',summary:"SOURCE-REVIEWED 2026-11-22 against official OOR RTKL statutory PDF, fee schedule, and police-recordings guidance; not exhaustively certified. ELIGIBILITY: §102 defines requester as legal US resident, not necessarily Pennsylvania resident. REQUEST: §§702-703 allow oral or anonymous requests but statutory remedies require written request to agency open-records officer, identifying records sufficiently and providing name and response address; no general purpose statement. RESPONSE: §901 requires agency response within five business days or deemed denial, NOT guaranteed production. §902 permits a timely written notice of qualifying extension up to 30 calendar days; longer extensions require requester agreement or deemed denial. DENIAL: §903 requires written reasons and appeal instructions; §706 requires segregating nonexempt portions. FEES: §1307 and OOR Dec. 30, 2024 schedule: black-and-white copies up to $0.25/page for first 1,000, $0.20 thereafter; color up to $0.50/page; ordinary electronic delivery, search, legal review and redaction carry no fee, with specific copying exceptions. Agency may waive fees; estimated charges above $100 may require prepayment. 2026 fee review pending: recheck schedule. EXEMPTIONS: §708(b) includes personal identification, some personnel records, public safety, criminal investigative §708(b)(16), and noncriminal investigative §708(b)(17) records; salaries and all disciplinary records are not categorically secret. Other laws and privilege may apply. Police audio/video recordings may fall under separate Act 22 of 2017, 42 Pa.C.S. Chapter 67A procedures; do not assume RTKL timelines. APPEALS: §§503,1101 generally allow 15 business days from denial mailing or deemed denial to appeal, usually to OOR, but local criminal-investigative appeals go to county DA designee and some agencies use separate officers. §§1301-1302 generally provide 30 days after mailing of final determination for judicial petition; court depends on agency. OPEN CHECKS: 2026 enacted amendments, revised fees, Act 22 request/appeal specifics, police discipline, 911 and CHRIA, court jurisdiction and case law.",links:[["OOR official statutory text","https://www.openrecords.pa.gov/Documents/RTKL/PA_Right-To-Know_Law.pdf?pdft=20220418"],["OOR official fees","https://www.openrecords.pa.gov/RTKL/FeeStructure.cfm"],["OOR police recordings","https://www.openrecords.pa.gov/RTKL/PoliceRecordings.cfm"],["OOR citizens guide","https://www.openrecords.pa.gov/RTKL/CitizensGuide.cfm"],["OOR current announcements","https://www.openrecords.pa.gov/"],["PA Attorney General request guidance","https://www.attorneygeneral.gov/right-to-know/"]]},'Rhode Island':{law:'Rhode Island Access to Public Records Act (APRA), R.I. Gen. Laws §§ 38-2-1–38-2-15',summary:'SOURCE-REVIEWED 2026-11-22 against Rhode Island Legislature §§38-2-2, 38-2-3, 38-2-4, 38-2-7 and 38-2-8 and official AG/Secretary of State guidance; NOT exhaustively certified. ELIGIBILITY: §38-2-3(a),(j) permits every person or entity to request public records; no residency, reason, or personal identification is generally required. REQUEST: Address a sufficiently identifiable request to the public body\'s designated records officer under its published procedures; a recognizable written request need not use the agency\'s form, and readily available public documents may be requested without writing (§38-2-3(d)). RESPONSE/PRODUCTION: §38-2-3(e) ordinarily requires inspection or copying within 10 BUSINESS DAYS after receipt, not merely acknowledgment; if unable, the body must promptly give a particularized written explanation and may take up to 20 ADDITIONAL BUSINESS DAYS if statutory undue-burden conditions are demonstrated. §38-2-7(b) makes untimely noncompliance a deemed denial, subject to lawful extension and payment exceptions. FEES: §38-2-4 caps ordinary paper copies at $0.15/page; search/retrieval at $15/hour after the first free hour; multiple requests by the same requester to the same body within 30 days are treated as one for this charge. Electronic copies limited to reasonable actual cost. Request advance estimate and itemization. §38-2-4(e) allows COURT reduction/waiver of qualifying public-interest search/retrieval fees; §38-2-7(b) waives copying/search/retrieval fees for untimely production unless waiting for properly charged payment. EXEMPTIONS: §38-2-2(4)(A) protects confidential/private personnel and medical material but identifies public employment data including name, salary, overtime, job title and termination date; peace officers\' municipality of residence is withheld. §38-2-2(4)(D) restricts criminal-investigative records only to the extent enumerated harms apply; law-enforcement management records and initial adult arrest/charge reports are public. Security plans, litigation protections, other statutory confidentiality and privacy may apply. §38-2-3(b) requires reasonably segregable nonexempt portions. DENIAL: §38-2-7(a) requires written specific reasons and appeal procedures, generally within 10 business days; missing reasons may be waived absent good cause. APPEAL: §38-2-8(a) permits (but does not necessarily require) review by chief administrative officer, decision due within 10 BUSINESS DAYS; §38-2-8(b) allows complaint to Attorney General after custodian denial or chief officer denial, or Superior Court relief with private counsel. AG\'s 2026 published decision explains chief-officer appeal is not prerequisite to AG complaint. No universal requester appeal-filing deadline was verified in the reviewed §38-2-8 text; do not invent one. OPEN CHECKS: Determine final enacted status/effective dates of 2026 APRA bills S2138/S2389 and any other amendments; confirm current §38-2-9 judicial remedies and limitation/accrual rules; body-camera/911 and police discipline special statutes/cases; agency-specific fee procedures and link monitoring.',links:[['RI Legislature §38-2-2 definitions/exemptions','https://webserver.rilegislature.gov/Statutes/TITLE38/38-2/38-2-2.HTM'],['RI Legislature §38-2-3 access/deadlines','https://webserver.rilegislature.gov/Statutes/TITLE38/38-2/38-2-3.HTM'],['RI Legislature §38-2-4 fees/waivers','https://webserver.rilegislature.gov/Statutes/TITLE38/38-2/38-2-4.HTM'],['RI Legislature §38-2-7 denial','https://webserver.rilegislature.gov/Statutes/TITLE38/38-2/38-2-7.HTM'],['RI Legislature §38-2-8 appeals','https://webserver.rilegislature.gov/Statutes/TITLE38/38-2/38-2-8.HTM'],['RI Attorney General complaint guidance','https://riag.ri.gov/about-our-office/divisions-and-units/civil-division/government-litigation/open-government'],['RI Secretary of State request guidance','https://www.sos.ri.gov/divisions/open-government-center/accessing-public-records']]},'South Carolina':{"law":"South Carolina Freedom of Information Act, S.C. Code §§ 30-4-10–110; body-worn cameras §23-1-240(G)","summary":"SOURCE-REVIEWED 2026-11-22 (NOT EXHAUSTIVE). ELIGIBILITY: Under §§30-4-20(b), 30-4-30(A), a person includes individuals and organizations; no general South Carolina residency requirement for initial access. Exception: individuals serving imprisonment sentences in correctional facilities are excluded from the ordinary §30-4-30(A) access right, without eliminating constitutional rights. REQUEST: Send a dated, specific written request to the holding public body, requesting inspection or electronic copies and an itemized fee estimate. Under §30-4-30(D), certain recent minutes, crime reports, jail lists and meeting materials must be available for in-person inspection without a written request, subject to exemptions. DETERMINATION VS PRODUCTION: Under §30-4-30(C), a written request generally requires a final availability determination and reasons within 10 working days (excluding weekends and legal holidays), or 20 working days for records older than 24 months. If granted, production generally must follow within 30 calendar days of the determination, or 35 calendar days for older records; if a lawful deposit is required, the production clock instead runs from receipt of the deposit. No timely determination means deemed approval only as to nonexempt records; exemptions remain. Written mutual extensions permitted. FEES/WAIVERS: §30-4-30(B) caps search, retrieval and redaction fees at actual cost and staff rate of the lowest-paid qualified employee; copying at prevailing commercial rate. No charge for legal disclosure review; no copying charge for electronic transmission. Up to 25% estimated reproduction deposit may be required. Public-interest fee reduction/waiver is discretionary; ask for estimate and waiver. EXEMPTIONS/PERSONNEL: §30-4-40(a)(2) privacy; (a)(3) law-enforcement materials only to extent enumerated harms apply; (a)(6) tiered public compensation disclosures; (a)(13) applicant materials with final-three exception. §30-4-50(A)(1) makes employee names, titles and employment dates public; §30-4-40(b) requires segregation and release of nonexempt portions. PUBLIC SAFETY: §30-4-50(A)(8) generally makes crime nature, substance and location reports public with lawful redactions. §30-4-50(A)(9) expressly covers specified vehicle dashboard-camera officer incidents, with special circuit-court withholding procedure. IMPORTANT: §23-1-240(G)(1) excludes BODY-WORN CAMERA footage from ordinary FOIA; discretionary release and discovery/court-order pathways differ, so never treat dashboard and body cameras identically. 911 dying-victim final statements receive special privacy redaction under §30-4-40(a)(2). DENIAL/COURT: Preserve agency determination and reasons; no universal administrative appeal in Chapter 4. §30-4-100(A) permits a SOUTH CAROLINA CITIZEN to seek circuit-court declaratory/injunctive relief within ONE YEAR of alleged violation or later public vote; this judicial standing requirement differs from initial requester eligibility. §30-4-100(B) addresses discretionary prevailing-party fees. OPEN QUESTIONS: Confirm 2026 enacted amendments beyond current codified text; police disciplinary-file case law and privacy balancing; 911 recording exceptions; exact court standing and limitations for nonresident requesters; agency-specific fee schedules. Official sections checked individually: §§30-4-20, 30-4-30, 30-4-40, 30-4-50, 30-4-100, 23-1-240(G).","links":[["South Carolina Legislature — FOIA definitions, deadlines, fees, exemptions, appeals (§§30-4-20–100)","https://www.scstatehouse.gov/code/t30c004.php"],["South Carolina Legislature — body-worn camera law (§23-1-240(G))","https://www.scstatehouse.gov/code/t23c001.php"],["South Carolina Legislature — 2025–2026 proposed body-camera amendment (not enacted in reviewed record)","https://www.scstatehouse.gov/sess126_2025-2026/bills/3288.htm"]]},'New York':{law:'New York Freedom of Information Law (FOIL), Public Officers Law Article 6, §§ 84–90',summary:'SOURCE-REVIEWED 2026-11-21 (not certified exhaustive). ELIGIBILITY: Any person may request nonexempt agency records under Public Officers Law §§86–89; courts are outside the agency definition and the Legislature has separate provisions. REQUEST: Reasonably describe existing records and send a written request to the holding agency records access officer; email is accepted when the entity has reasonable means, and state agencies with websites must support online requests. No general residency or purpose showing required; special certification applies to solicitation-oriented name/address lists. RESPONSE VS PRODUCTION: §89(3)(a) requires the agency within FIVE BUSINESS DAYS to provide records, deny in writing, or acknowledge in writing with an approximate reasonable response date. The usual 20-business-day period runs from acknowledgment, NOT the initial request; when disclosure cannot occur within that period, the agency must give a written reason and a reasonable date certain. This is NOT an unconditional 5-day production mandate. FEES: §87(1)(b)-(c) ordinarily caps standard paper photocopies at 25 cents per page up to 9 by 14 inches; other copies may be charged at narrowly defined actual reproduction costs. Search and administrative time are excluded; qualifying employee copying time is chargeable only if at least two hours is needed. No general statutory public-interest waiver was confirmed; free inspection of accessible records is available. EXEMPTIONS: §87(2) requires particularized, specific justification rather than blanket category denials. Statutory confidentiality, personal privacy, specified law-enforcement harms, safety, and certain internal materials may justify redaction/withholding. §86(6)-(9) defines law-enforcement disciplinary records, including complaints, proceedings and dispositions; §89(2-b) requires redaction of enumerated personal/medical details and §89(2-c) permits technical-infraction redaction. Do not characterize all officer discipline or police investigations as automatically secret. DENIAL AND APPEAL: §89(4)(a) generally allows a written agency appeal within 30 calendar days of denial, including constructive denial from missed response rules; the appeals officer must grant access or explain continued denial within 10 BUSINESS DAYS. §89(4)(b) permits Article 78 judicial review after adverse administrative determination. CPLR §217(1) generally provides FOUR MONTHS from final and binding determination or qualifying refusal, subject to accrual and special-case rules; do not confuse this with the 30-day internal appeal. The Committee on Open Government offers advice, not binding adjudication. SPECIAL: §89(5) trade-secret/critical-infrastructure exception disputes have distinct seven-business-day appeals and possible 15-day court periods for exception claimants; do not apply the general deadlines to those cases. OPEN: verify recent case law on unsubstantiated officer discipline, body-camera video, sealed criminal records, agency-specific fees, Article 78 accrual, and later legislative amendments. Official statutory links checked 2026-11-21.',links:[['NY Senate — Public Officers Law §86 definitions','https://www.nysenate.gov/legislation/laws/PBO/86'],['NY Senate — §87 access, exemptions and fees','https://www.nysenate.gov/legislation/laws/PBO/87'],['NY Senate — §89 procedures and appeals','https://www.nysenate.gov/legislation/laws/PBO/89'],['NY Senate — CPLR §217 judicial filing period','https://www.nysenate.gov/legislation/laws/CVP/217'],['NY Committee on Open Government — FOIL rules and FAQ','https://opengovernment.ny.gov/freedom-information-law'],['NY Committee — advisory role','https://opengovernment.ny.gov/node/186']]},'North Carolina':{law:'North Carolina Public Records Law, N.C. Gen. Stat. Chapter 132',summary:"SOURCE REVIEW 2026-11-21 (official North Carolina General Assembly statutes; not exhaustive). ELIGIBILITY / REQUEST: Any person may inspect public records; no general residency or purpose requirement. Address a reasonably described request to the record custodian; Chapter 132 generally does not require a particular form, but database-copy requests may be required in writing (§§132-6, 132-6.2(c)). TIMING: Inspection at reasonable times and copies as promptly as possible; no universal five-day or other numeric acknowledgment/production deadline (§132-6). FEES: Uncertified copies generally limited to actual reproduction cost; reasonable additional special-service charges for extensive IT or clerical/supervisory assistance. State CIO/designee can mediate disputed charges (§132-6.2). No general mandatory fee waiver confirmed. EXEMPTIONS: Confidential content must be separated at agency expense (§132-6(c)); criminal investigative/intelligence files generally excluded, while specified incident/arrest information remains public (§132-1.4). Body/dash recordings are governed by distinct disclosure and court-release procedures, not ordinary Chapter 132 access (§132-1.4A; includes 2026 amendment). City employee personnel files are generally confidential except enumerated public employment information and statutory access rights, including employee access with exceptions (§160A-168); county/state employees require separate statutes. DENIAL / REVIEW: Denied requesters may seek judicial disclosure under §132-9, subject to mediation procedure §7A-38.3E; after responsive pleadings mandatory mediation initiation is due within 30 days. No universal administrative appeal or judicial filing limitation established by this review; verify case-specific deadlines with counsel. UNRESOLVED: County/state personnel statutes, 911 and other specialized confidentiality, body-camera 2026 amendment effect, waiver exceptions, applicable limitation periods and case law. Not attorney-reviewed.",links:[["NC Legislature — public-records definition §132-1","https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_132/GS_132-1.html"],["NC Legislature — inspection and timing §132-6","https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_132/GS_132-6.html"],["NC Legislature — fees §132-6.2","https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_132/GS_132-6.2.html"],["NC Legislature — criminal investigations §132-1.4","https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_132/GS_132-1.4.html"],["NC Legislature — body-camera recordings §132-1.4A","https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_132/GS_132-1.4A.html"],["NC Legislature — court enforcement §132-9","https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_132/GS_132-9.html"],["NC Legislature — mediation §7A-38.3E","https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_7A/GS_7A-38.3E.html"],["NC Legislature — city personnel §160A-168","https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_160A/GS_160A-168.html"]]},'North Dakota':{law:'North Dakota Constitution art. XI, § 6; N.D.C.C. §§ 44-04-17.1, 44-04-18, 44-04-18.1, 44-04-18.3, 44-04-18.7, 44-04-18.10, 44-04-21.1',summary:'SOURCE-REVIEWED 2026-11-21 (not certified exhaustive). ELIGIBILITY / REQUEST: Anyone, regardless of residence or motive, may request reasonably identified existing public-entity records orally, by email, mail, telephone or in person. The agency generally cannot demand requester identity, purpose or a written initial request, but may require written clarification of unclear records. Courts are generally outside this open-records framework. RESPONSE VS PRODUCTION: No universal numerical acknowledgment or production deadline; agency must provide available nonexempt records or explain the specific legal basis for withholding within a REASONABLE time depending on scope and circumstances. An unreasonable delay can violate §44-04-18. FEES: Inspection is generally free; standard paper copies up to 25 cents per impression; nonpaper copying at actual cost; first hour of locating and first hour of redaction free, then each up to $25/hour; additional actual technology costs may apply for qualifying electronic production. Advance payment of estimated fees can be required. No general mandatory public-interest fee waiver verified; ask the entity whether discretionary relief is available. EXEMPTIONS: §44-04-18.10 requires release of segregable open portions. Exempt records may be withheld at agency discretion; confidential information must be protected. Employee salaries and job performance are generally open, but employee medical records, specified contact data and other identifiers receive protection under §§44-04-18.1 and 44-04-18.3. Misconduct internal investigations may be temporarily exempt until completion or 75 days, whichever first. Under §44-04-18.7 active criminal intelligence/investigations, officer safety and specified body-camera imagery can be exempt; do not presume all police records or all body camera footage are categorically secret. Special rules cover 911 recordings, victims and Marsy\'s Law. DENIAL / REVIEW: Ask for a written denial citing the specific legal authority or confirming nonexistence. Under §44-04-21.1 an interested person generally must request an Attorney General opinion within 30 DAYS of the alleged open-records violation, not 30 days after learning of it. AG opinion requests require contact details; do not confuse this with a universal judicial filing deadline. Court enforcement and its limitations must be independently evaluated. CHECKED: 2026-11-21 against ND Attorney General March 2026 Open Records Guide, official requesting-records and opinion-request guidance; section-level statutory references cross-checked against the guide, but current codified text and post-guide amendments still need independent section-by-section confirmation. OPEN QUESTIONS: Confirm current §44-04-21.1 remedial court deadlines, statutory fee exceptions, law-enforcement body-camera private-place definitions, 911 transcript/listening access, and any later 2026 changes.',links:[['North Dakota Attorney General — March 2026 Open Records Guide','https://attorneygeneral.nd.gov/wp-content/uploads/2026/03/2026-03-OR-Guide.pdf'],['North Dakota Attorney General — requesting public records','https://attorneygeneral.nd.gov/open-records-meetings/requesting-public-records/'],['North Dakota Attorney General — request an opinion','https://attorneygeneral.nd.gov/attorney-generals-office/email-attorney-general-opinion-request/'],['North Dakota Attorney General — manuals and law-enforcement checklist','https://attorneygeneral.nd.gov/open-records-meetings/manuals-and-guides/']]},Ohio:{law:'Ohio Public Records Act, Ohio Rev. Code § 149.43 (effective September 7, 2026)',summary:'SOURCE REVIEW — 2026-11-21. REQUESTER / METHOD: Any person generally may request reasonably identified existing records orally, in writing, or electronically without giving a reason or identity; statutory exceptions apply, including certain incarcerated requesters and protected employee information. Ask the office holding the records; a written dated request preserves evidence. RESPONSE VS PRODUCTION: §149.43(B)(1) requires prompt inspection and copies at cost within a reasonable period; there is NO universal fixed acknowledgment or production day count. Agencies must help clarify overly broad requests. FEES / WAIVERS: Ordinary copies generally at actual reproduction cost; inspection is free, with delivery/postage potentially prepaid. No general mandatory hardship waiver. Under §149.43(B), qualifying law-enforcement/prosecutor video preparation may cost actual expense capped at $75 per hour of video and $750 total; an estimate is due within five business days, and eligible victims/counsel/insurers may receive a statutory fee exemption with required affidavit. EXEMPTIONS: §149.43(A) includes confidential law-enforcement investigatory records (a defined, limited category), protected portions of body/dash camera video, trial-preparation, medical, designated public-service-worker residential/family information, and automated-license-plate-reader database images/data; §149.433 protects defined security/infrastructure records. Do not treat every police or personnel record as automatically exempt; segregate and disclose nonexempt portions. DENIAL: §149.43(B)(3) requires an explanation citing legal authority; if the request was written, explanation must be written. REVIEW — CRITICAL 2025/2026 CHANGE: Before filing a public-records lawsuit, serve a complaint under Civil Rule 4 on the custodian and allow THREE BUSINESS DAYS to cure; file a written affirmation of service and elapsed cure period with the suit or it must be dismissed. After that choose a §2743.75 Court of Claims/common-pleas complaint OR a §149.43(C) mandamus action, not both; consult §2743.75 for court-specific appeal deadlines. No universal initial administrative appeal deadline is supplied by §149.43. UNRESOLVED: Confirm specific personnel disciplinary records, 911 dispatch recordings, body-camera restricted-portion consent, appellate time limits and any later amendments before case-specific advice. Official text checked 2026-11-21; not an exhaustive audit.',links:[['Ohio Revised Code §149.43 — current (effective 2026-09-07)','https://codes.ohio.gov/ohio-revised-code/section-149.43/9-7-2026'],['Ohio Revised Code §2743.75 — records court procedure','https://codes.ohio.gov/ohio-revised-code/section-2743.75'],['Ohio Revised Code §149.433 — security and infrastructure','https://codes.ohio.gov/ohio-revised-code/section-149.433'],['Ohio Attorney General — 2026 Sunshine Laws Manual','https://www.ohioattorneygeneral.gov/Files/Publications-Files/Publications-for-Legal/Sunshine-Laws-Publications/2026-Sunshine-Manual.aspx']]},Oklahoma:{"law":"Oklahoma Open Records Act, 51 O.S. §§ 24A.1–24A.40 (official sources checked 2026-11-21; further 2026 amendment verification pending)","summary":"REQUESTER / METHOD: Public access is generally available to any person; direct a reasonably specific request to the custodian. Agencies may have their own submission procedures, but the Attorney General office's required form is not a statewide requirement. RESPONSE / PRODUCTION: §24A.5 requires prompt, reasonable access; no universal fixed acknowledgment or production deadline. Delays should be limited to preparing records and avoiding excessive disruption of essential functions. FEES: Under §24A.5, ordinary copying generally up to $0.25/page or $1/certified page; higher reasonable search fees may apply to commercial or excessively disruptive requests, but public-interest requests (including news media, scholars and taxpayers) are protected against search charges. Agencies post fee schedules; discretionary waivers and agency-specific charges require confirmation. EXEMPTIONS: §24A.7 permits withholding certain internal personnel investigations and records whose disclosure would constitute a clearly unwarranted invasion of personal privacy; employees' own-file access is separately protected by §24A.7(C) absent other confidentiality law. §24A.8 makes enumerated basic law-enforcement information accessible while allowing discretion to withhold other investigative records, subject to judicial public/individual-interest balancing. Do not presume all 911 audio, body-camera footage or internal affairs records are categorically public. DENIAL / REMEDIES: Preserve request, correspondence and exemption citations. §24A.17 provides civil injunctive/declaratory remedies and attorney-fee rules; before seeking declaratory or injunctive relief, give the public body/official ten business days' notice and copy the Attorney General. §24A.40 establishes an Attorney General Public Access Counselor complaint/advisement route; do not confuse it with a court appeal or assume a universal filing deadline. UNRESOLVED: Verify latest consolidated 2026 statutory amendments and §24A.40 complaint timing; agency-specific fee schedules, BWC/911 exceptions, personnel/disciplinary case law, and applicable judicial limitations. Not certified fully audited.","links":[["Oklahoma Attorney General — Open Records Act summary (updated July 2025)","https://oklahoma.gov/content/dam/ok/en/oag/open-records/oma-and-ora-resources/Open%20Records%20One%20Pager.pdf"],["Oklahoma Senate — Title 51 statutory compilation (check amendments)","https://oksenate.gov/sites/default/files/2022-05/os51.pdf"],["Oklahoma Attorney General — 2026 personnel-file access advisement","https://oklahoma.gov/oag/opinions/pac/opinions-advisements/pac-advisements/2026/061.html"],["Oklahoma Attorney General — 2026 911 recording advisement","https://oklahoma.gov/oag/opinions/pac/opinions-advisements/pac-advisements/2025/070.html"],["Oklahoma Attorney General — 2025 investigative record advisement","https://oklahoma.gov/oag/opinions/pac/opinions-advisements/pac-advisements/2025/002.html"]]},Nebraska:{"law":"Nebraska Public Records Statutes, Neb. Rev. Stat. §§ 84-712–84-712.09 (checked 2026-11-20)","summary":"REQUESTER / METHOD: Any citizen or other interested person may examine records; direct a specific written request to the lawful custodian for copies and statutory response rights. Nebraska resident means a domiciled person and includes news media regardless of domicile; nonresidents may request but face different fees. RESPONSE / PRODUCTION: Under § 84-712(4), within four business days of actual receipt of a written request the custodian must estimate costs and provide records, give a statutory written denial, or explain delay in writing with the earliest practicable fulfillment date and an opportunity to narrow or prioritize. Four days is not an unconditional final production deadline. Requesters generally have ten business days to respond to the cost estimate or processing need not proceed. FEES / WAIVERS: § 84-712(3) allows actual added costs. Nebraska residents receive the first eight cumulative hours of search, identification, physical redaction or copying without existing staff salary charges; legal-basis attorney review cannot be charged. Nonresidents may be charged staff and attorney review time. Deposits may be required above $50 estimated copying cost; public-interest waivers/reductions are permitted. EXEMPTIONS: § 84-712.05(5) permits withholding qualifying investigative, intelligence, informant and tactical law-enforcement records, but not all police records categorically. Subsection (8) concerns personal personnel information except salaries and routine directory information; subsection (9) protects specified security vulnerabilities. Other medical and statutory confidentiality rules apply. § 84-712.06 requires reasonably segregable public portions to be released. DENIAL: § 84-712.04 requires a written, record-specific statutory explanation, responsible official's name, and review rights. APPEAL / REVIEW: § 84-712.03 allows Attorney General petition (15-calendar-day determination period, NOT a requester filing deadline) or district-court mandamus; § 84-712.07 allows equitable relief and possible fees for substantially prevailing requesters. No universal requester filing deadline was verified from these provisions. UNRESOLVED: Specialized body-camera, 911 and criminal-justice confidentiality rules, case-specific court limitation periods, and agency fee schedules require further review. RESEARCH STATUS: Official §§ 84-712, 84-712.01, 84-712.03 through 84-712.07 source-checked 2026-11-20; not certified exhaustive.","links":[["Nebraska Legislature — official Chapter 84 statutory text","https://www.nebraskalegislature.gov/laws/laws-index/chap84-full.html"],["Nebraska Attorney General — public-records overview","https://ago.nebraska.gov/public-records"],["Nebraska AG — March 2026 police-records determination","https://ago.nebraska.gov/sites/default/files/doc/2026-1020%3B%20Scottsbluff%20Police%20Department%3B%20James%20Edwards%2C%20Petitioner.pdf"]]},Nevada:{law:'Nevada Public Records Act — NRS Chapter 239',summary:'SOURCE CHECKED 2026-11-20 (not exhaustive). ELIGIBILITY: NRS 239.010 and 239.0107 generally allow a person to request nonconfidential public records; no Nevada residency restriction identified in these provisions. REQUEST: NRS 239.0107 accepts oral or written requests to the governmental entity with legal custody or control. Executive agencies publish their forms and procedures under NRS 239.008; written requests help document receipt. RESPONSE vs PRODUCTION: By the end of the fifth business day, the agency must provide access/copies, give written notice that it lacks custody (and identify the custodian if known), give written notice of the earliest reasonably expected availability with follow-up explanations if delayed, or deny confidential material in writing citing specific legal authority. This is NOT a universal five-day final-production deadline. Readily available records must be provided as expeditiously as practicable. FEES: NRS 239.052 generally caps copying fees at actual cost absent a specific fee statute or regulation; an agency may waive fees under a posted written policy. Executive-agency regulation NAC 239.864 requires an estimate when estimated actual cost exceeds $25 and allows a deposit. EXEMPTIONS: NRS 239.010 requires segregation/redaction of confidential portions when feasible. Confidentiality can arise under other state/federal laws; police investigations, victim information, employee/personnel and medical records need record-specific review rather than blanket claims. DENIAL/REMEDIES: Under NRS 239.0107(1)(d), a confidentiality denial must cite the specific statute or other legal authority. NRS 239.011 allows district-court relief for denial, unreasonable delay, or improper/excessive copying fees; the statute does not establish a universal 30-day requester filing deadline. Verify court rules and applicable limitations with counsel. OPEN QUESTIONS: specialized law-enforcement and body-camera restrictions; personnel confidentiality and case law; specific agency fee schedules; litigation filing limitations and 2025 amendments to NRS 239.011. Primary statute and executive-agency regulation reviewed; NOT certified as a comprehensive state audit.',links:[['Nevada Legislature — NRS Chapter 239 (2025 text, revised April 2026)','https://www.leg.state.nv.us/Division/Legal/LawLibrary/NRS/NRS-239.html'],['Nevada Legislature — NAC Chapter 239 executive-agency rules','https://www.leg.state.nv.us/Division/Legal/LawLibrary/NAC/NAC-239.html'],['Nevada State Library — official public-records request guidance','https://nsla.nv.gov/public-records']]},'New Hampshire':{law:'New Hampshire Right-to-Know Law, RSA Chapter 91-A',summary:'SOURCE CHECK: 2026-11-21 (official New Hampshire General Court statutory text; substantive review, not exhaustive certification). ELIGIBILITY / REQUEST: RSA 91-A:4(I) says every citizen may inspect and copy nonexempt governmental records during regular business hours; submit a reasonably described request to the public body or agency holding the records. The statute does not impose a universal written-request-only rule; a dated written request is useful for proof. RESPONSE VS PRODUCTION: Records immediately available must be provided for inspection/copying; otherwise, within 5 business days the agency must provide records, deny, or give a written statement of the time reasonably needed to decide and the reason for delay, plus an itemized estimate if the special electronic-communications charge applies. Five days is NOT a universal final-production deadline. FEES / WAIVERS: Inspection and delivery without copying generally are free; actual copying costs may apply. RSA 91-A:4(VIII) separately permits a reasonable charge for electronic-communications requests above 250 communications, capped at $1 per communication, subject to counting and aggregation rules. The special charge is waived for qualifying indigency or public-interest requests under subsection IX; do not describe this as a universal waiver of all copying fees. EXEMPTIONS: RSA 91-A:5(IV) covers internal personnel practices and personnel/medical and other files where disclosure would invade privacy; disclosure requires record-specific analysis, not a blanket police-personnel exclusion. RSA 91-A:5(VI) covers certain emergency-preparedness security records. RSA 91-A:5(X) generally exempts police body-camera recordings under RSA 105-D but provides conditional exceptions for use of force, firearm discharge, and felony-arrest encounters, subject to privacy and other exemptions. RSA 91-A:4(I-a) specifically opens certain additional employee separation payments. DENIAL: RSA 91-A:4(IV)(c) requires written identification of the specific exemption and brief explanation of its application. REMEDIES / DEADLINES: RSA 91-A:7 permits superior-court petition OR ombudsman complaint; choosing a route affects access to the other. Under RSA 91-A:7-b, the ombudsman complaint carries a $25 fee that may be waived for inability to pay. Under RSA 91-A:7-c, appeal of the ombudsman final ruling to superior court is due within 30 CALENDAR days; this is NOT a universal 30-day deadline to challenge an initial agency denial. OPEN QUESTIONS: confirm current court filing limitations for direct petitions, records governed by other police-investigation confidentiality statutes, case-law treatment of personnel privacy, agency-specific copy charges, and whether any subsequent 2026 enactments affect these provisions. General education only; verify before relying on a deadline.',links:[['NH General Court — RSA 91-A:4 access, deadlines, charges and waivers','https://gc.nh.gov/rsa/html/VI/91-A/91-A-4.htm'],['NH General Court — RSA 91-A:5 exemptions and body cameras','https://gc.nh.gov/rsa/html/VI/91-A/91-A-5.htm'],['NH General Court — RSA 91-A:7 court or ombudsman','https://gc.nh.gov/rsa/html/VI/91-A/91-A-7.htm'],['NH General Court — RSA 91-A:7-b ombudsman complaint','https://gc.nh.gov/rsa/html/VI/91-A/91-A-7-b.htm'],['NH General Court — RSA 91-A:7-c 30-day ombudsman appeal','https://gc.nh.gov/rsa/html/VI/91-A/91-A-7-c.htm']]},'New Jersey':{law:'New Jersey Open Public Records Act (OPRA), N.J.S.A. 47:1A-1 et seq.; P.L. 2024, c.16',summary:'SOURCE-REVIEWED 2026-11-21 (not a complete legal audit). ELIGIBILITY: Any person may seek nonexempt government records; anonymous requests are permitted, but an anonymous requester cannot bring the statutory denial challenge. REQUEST: Submit a written agency form or sufficiently complete letter/email to the designated records custodian; include required contact information (or identify as anonymous), record description, commercial-purpose certification and any litigation-related certification. A request is received only when it reaches the custodian. Broad email/text searches must identify accounts or job titles, subject matter and a reasonable period; requests requiring new research or record creation can be rejected. RESPONSE VS PRODUCTION: For currently available records, grant or deny access as soon as possible and ordinarily within 7 business days; 14 business days applies to commercial requests and specified protected-address reviews with notice within 7 days. Special fire-district periods and reasonable notified extensions apply. Archived records require timely notice and an availability date no more than 21 business days after that notice. Failure to respond within the applicable period can constitute a deemed denial, subject to statutory exceptions. FEES: Ordinarily 5 cents per letter page, 7 cents per legal page; electronic access generally free, with actual media costs and itemized reasonable special service or conversion charges where authorized. Statute permits deposits when reproduction is expected to exceed $5; eligible crime victims have specified free-copy rights. No general fee waiver should be assumed. EXEMPTIONS: Criminal investigatory records as specifically defined, certain victim records, public-safety/security systems, private identifiers and protected police/prosecutor home addresses; personnel-related grievance and sexual-harassment records have specific exclusions. Not all police records or all employment information are categorically closed: salary/overtime and contracts ordinarily receive immediate access, subject to age and other exceptions. Redact exempt portions and release reasonably separable remainder. DENIAL: Custodian must state specific basis; appeal information must be available. REVIEW: An accurately identified requester generally has 45 days from denial to file in Superior Court or complain to the Government Records Council under 47:1A-6; do not rely on superseded pre-2024 GRC 60-day guidance. UNRESOLVED: Check specialized body-worn-camera and internal-affairs disclosure laws, exact application of litigation/discovery restriction, fee disputes, and recent amendments/case law before individualized reliance.',links:[['NJ Legislature — OPRA definitions and exemptions (2024 enactment)','https://pub.njleg.state.nj.us/Bills/2024/PL24/16_.HTM'],['NJ Legislature — current N.J.S.A. 47:1A-5 request and response rules','https://lis.njleg.state.nj.us/nxt/gateway.dll/statutes/1/45122/45146'],['NJ Government Records Council — OPRA statutory text','https://www.nj.gov/grc/laws/act/index.html'],['NJ Government Records Council — official guidance','https://www.nj.gov/grc/']] },'New Mexico':{law:"New Mexico Inspection of Public Records Act, NMSA 1978 §§ 14-2-1–14-2-12",summary:"SOURCE-REVIEWED 2026-11-21 (not certified exhaustive). ELIGIBILITY: IPRA §14-2-1 grants every person inspection rights; no residency restriction identified. REQUEST: Under §14-2-8, oral requests are possible, but statutory procedures and penalties apply to written requests. Address the records custodian and provide requester name, address, telephone number, and a reasonably particular description; no general reason statement required. RESPONSE VS PRODUCTION: §14-2-8 requires inspection immediately/as soon as practicable, ordinarily no later than 15 calendar days after written custodian receipt. If inspection cannot occur within 3 business days, the custodian must explain in writing when inspection or another response will occur. The three-business-day communication is NOT a production deadline. §14-2-10 allows additional reasonable time for properly identified excessively burdensome or broad requests, with written notice. FEES: §14-2-9 requires release of segregable nonexempt portions; electronic copies of electronically held records may be requested in existing format. Reasonable copying charges are allowed, capped at $1 per printed page up to 11 x 17 inches; actual transmission/media charges may apply, and no fee for determining disclosability. The DOJ provides electronic copies free under its own policy, not a universal statutory waiver. EXEMPTIONS: §14-2-1 protects specified medical records, employment reference letters, opinion material in personnel files, qualifying law-enforcement information and other specifically confidential material; do not treat every police personnel or investigative record as automatically exempt. DENIAL / ENFORCEMENT: §14-2-11 provides written explanation of denial and a deemed-denial mechanism generally after 15 calendar days, subject to broad/burdensome requests. §14-2-12 authorizes district-court enforcement by a denied requester, AG or district attorney; DOJ accepts informal complaints but that process is not a mandatory universal administrative appeal. No universal 30-day judicial appeal deadline verified. CAUTION: 2025 HB 283 and HB 497 are bill texts, NOT proof of enacted amendments; do not adopt their proposed 21-business-day or notice-before-suit language without session-law confirmation. OPEN: verify 2026 enactments and the official compiled statute, law-enforcement body-camera/911 and disciplinary confidentiality, case-specific filing limitation, and current court decisions. DOJ warns its IPRA guide does not yet incorporate the October 30, 2024 Albuquerque Journal appellate decision.",links:[["New Mexico DOJ — IPRA statutory procedures and enforcement","https://nmdoj.gov/get-help/inspection-of-public-records-act/"],["New Mexico DOJ — compliance guide and stated case-law limitation","https://nmdoj.gov/publications/compliance-guides/"],["New Mexico DoIT — agency request deadlines and fees","https://www.doit.nm.gov/about/ipra"],["New Mexico courts — official statute access instructions","https://nmcourts.gov/wp-content/uploads/sites/25/2024/08/OVER14-YEARS-OLD.pdf"],["New Mexico Legislature — 2025 HB 497 proposed amendments (not enacted-law evidence)","https://www.nmlegis.gov/Sessions/25%20Regular/bills/house/HB0497.HTML"]]},Maine:{law:'Maine Freedom of Access Act, 1 M.R.S. §§ 400–414',summary:'AUDITED 2026-11-19: Under 1 M.R.S. §408-A any person may request records without a written or in-person submission. A sufficiently described request must be acknowledged within five working days; a good-faith, nonbinding production estimate follows, not a five-day production mandate. A denial or expected denial requires written notice within five working days; under 2025 amendments a written denial must cite statutory authority. Standard black-and-white copies are capped at 10 cents per page; no per-page electronic fee; first two staff hours free then up to $25 per hour. Indigency and public-interest fee waivers are discretionary. Confidential records under §402(3) and other laws require specific assessment, including law-enforcement and personnel restrictions. Under §409(1) an aggrieved requester generally has 30 calendar days after written denial or failure notice to appeal to Superior Court. OPEN: no-written-notice appeal trigger and record-specific confidentiality need case-specific verification. PRIMARY SOURCES checked 2026-11-19: §§408-A, 409, 402.',links:[['Maine Legislature — §408-A','https://legislature.maine.gov/legis/statutes/1/title1sec408-A.html'],['Maine Legislature — §409','https://legislature.maine.gov/legis/statutes/1/title1sec409.html'],['Maine Legislature — §402','https://legislature.maine.gov/legis/statutes/1/title1sec402.html']]},Maryland:{law:'Maryland Public Information Act, Md. Code General Provisions §§ 4-101–4-601',summary:'AUDITED 2026-11-19: Maryland PIA General Provisions Title 4 permits public requests to custodians, subject to person-in-interest restrictions for certain records. §4-203 ordinarily requires grant/denial promptly within 30 days and production immediately or within reasonable retrieval time, no later than 30 days; §4-356 matters have a 50-day decision rule. If production will exceed ten working days, send a written/email estimate of time, fee range and reason for delay within ten working days. Consensual extensions up to 30 days and dispute-resolution tolling apply. Denials require reasons, legal authority, record description and remedy notice within ten working days after denial. §4-206 provides two free hours of search/preparation and reasonable actual-cost fees; indigency/public-interest waivers may be requested. §4-311 generally protects personnel records but excludes many police misconduct investigations, internal affairs records, hearings, disciplinary decisions and unsolicited positive community feedback; technical infractions remain personnel records, and other exemptions may still apply. §4-362 provides circuit-court remedies; Ombudsman/Compliance Board routes have separate prerequisites. OPEN: Board procedural deadlines and specialized investigative exemptions need further validation. PRIMARY SOURCES checked 2026-11-19: §§4-203, 4-206, 4-311, 4-362.',links:[['Maryland Legislature — §4-203','https://mgaleg.maryland.gov/mgawebsite/Laws/StatuteText?article=ggp&section=4-203&enactments=false'],['Maryland Legislature — §4-206','https://mgaleg.maryland.gov/mgawebsite/Laws/StatuteText?article=ggp&section=4-206&enactments=false'],['Maryland Legislature — §4-311','https://mgaleg.maryland.gov/mgawebsite/Laws/StatuteText?article=ggp&section=4-311&enactments=false'],['Maryland Legislature — §4-362','https://mgaleg.maryland.gov/mgawebsite/Laws/StatuteText?article=ggp&section=4-362&enactments=false']]},Mississippi:{law:'Mississippi Public Records Act, Miss. Code Ann. §§ 25-61-1 through 25-61-19',summary:'SOURCE CHECKED 2026-11-20 (Mississippi Ethics Commission official statutory text and complaint guidance; cross-checked 2025 codification for amended deadlines). ELIGIBILITY / REQUEST: Any person may request public records from a public body. Follow the agency published reasonable written procedures; if none exist, §25-61-5 describes access within one working day after a written request. DEADLINES: §25-61-5 generally requires production or denial within seven working days. If production is not possible by day seven, the body must give a particularized written explanation; absent mutual agreement, production generally cannot be later than 14 working days. These are access/production rules, not merely acknowledgment periods; procurement tolling is a statutory exception. FEES: §25-61-7 generally caps search, review, copying and mailing charges at actual cost, with staff time at the lowest competent pay level; special electronic/GIS fee provisions apply. No general statutory fee-waiver entitlement was confirmed. EXEMPTIONS: §25-61-12 protects law-enforcement investigative reports in agency possession but expressly treats incident reports as public; victim identities and officers private contact information receive protection. §25-1-100 restricts personnel files; §25-61-11 preserves other statutory confidentiality. Nonexempt portions must be segregated/redacted under §25-61-5. DENIAL / REMEDY: A denial must be written and identify the specific exemption; §25-61-13 authorizes complaints to the Ethics Commission and chancery-court review/enforcement. The Commission says attach a written denial if available; the public body has 14 days to respond to the Commission. Do not confuse this agency response with the records-production deadline. UNRESOLVED: Confirm current Commission procedural filing limits and judicial review deadlines before litigation; verify specialized body-camera, criminal-history and personnel statutes and any 2026 enactments for particular records. The official Commission web text may not reflect all recent amendments; use current enacted statute for controlling language.',links:[['Mississippi Ethics Commission — Public Records Act and complaint process','https://www.ethics.ms.gov/publicrecords'],['Mississippi Ethics Commission — statutory chapter text','https://www.ethics.ms.gov/thepublicrecordact'],['2025 Mississippi Code §25-61-5 (cross-check, secondary publication)','https://law.justia.com/codes/mississippi/title-25/chapter-61/section-25-61-5/'],['2025 Mississippi Code chapter 61 index (secondary cross-check)','https://law.justia.com/codes/mississippi/title-25/chapter-61/']]},Missouri:{law:'Missouri Sunshine Law, Mo. Rev. Stat. Chapter 610 (official sources checked November 20, 2026)',summary:'SOURCE-BY-SOURCE REVIEW — 2026-11-20. ELIGIBILITY / REQUEST: Public records are available to the public under section 610.023; request from the particular governmental body custodian, whose identity and location must be disclosed upon request. No mandatory request form; a dated written or emailed request helps preserve evidence. RESPONSE VS PRODUCTION: Section 610.023(3) requires action as soon as possible, no later than the end of the third business day after custodian receipt. This is not an unconditional three-day production deadline: when immediate access is unavailable, the custodian must explain the delay and earliest availability; production may exceed three days for reasonable cause. DENIAL: Under 610.023(4), upon request, the custodian must provide written grounds citing the specific legal provision within three business days of that follow-up request. FEES: Section 610.026 generally caps ordinary paper copies (up to 9 x 14 inches) at 10 cents per page, permits clerical duplication time and actual research costs, and requires lowest-cost capable staff. Electronic and special-format costs differ. Public-interest fee waivers or reductions may be available. IMPORTANT 2025 AMENDMENT: Under 610.026(2), a request can be deemed withdrawn if fees or clarification are not provided within 90 days, or 150 days for requested fees over $1,000, subject to statutory notice and litigation exceptions; pending-on-August-28-2025 requests have a special January 1, 2026 provision. EXEMPTIONS: Section 610.021 allows closure of specified litigation, personnel hiring/firing/discipline/performance, and security-related materials, but not every police personnel record is automatically closed; some final employee votes must become public within 72 hours. Segregate exempt from nonexempt information under 610.024. LAW ENFORCEMENT: Section 610.100 generally opens incident and arrest reports, subject to special rules (including arrests without charges after 30 days), while investigative reports and mobile video recordings are generally closed until investigations become inactive; additional privacy, safety, nonpublic-location and court-ordered disclosure rules apply. Certain incident participants have a separate written-request/court-motion process under 610.100(4), with a 30-day agency action provision. REVIEW: An Attorney General Sunshine complaint is available but is not a guaranteed appeal or representation; judicial enforcement under 610.027 is in circuit court. The one-year ascertainability / two-year outside limit in 610.027(5) expressly addresses suits to void governmental action; do NOT assume it is a universal records-denial appeal deadline. UNRESOLVED: Check 2026 legislation and specialized 911, body-camera distribution, police employment, and record-specific court remedies before relying on a deadline. Educational summary, not legal advice.',links:[['Missouri Revisor — §610.023 custodian, response and denial','https://revisor.mo.gov/main/OneSection.aspx?section=610.023'],['Missouri Revisor — §610.026 fees and 2025 withdrawal amendment','https://revisor.mo.gov/main/OneSection.aspx?section=610.026'],['Missouri Revisor — §610.021 closed records and personnel','https://revisor.mo.gov/main/OneSection.aspx?section=610.021'],['Missouri Revisor — §610.024 segregating closed information','https://revisor.mo.gov/main/OneSection.aspx?section=610.024'],['Missouri Revisor — §610.100 law-enforcement records','https://revisor.mo.gov/main/OneSection.aspx?section=610.100'],['Missouri Revisor — §610.027 judicial enforcement','https://revisor.mo.gov/main/OneSection.aspx?section=610.027'],['Missouri Attorney General — Sunshine Law procedures and complaint','https://ago.mo.gov/get-help/programs-services-from-a-z/sunshine-law/'],['Missouri Attorney General — records request model','https://ago.mo.gov/get-help/programs-services-from-a-z/sunshine-law/sample-language-forms/records-request-form/']]},Montana:{law:'Montana Constitution Art. II, §§ 9–10; MCA §§ 2-6-1002, 2-6-1003, 2-6-1006, 2-6-1009; Title 44, chapter 5',summary:'SOURCE-CHECKED 2026-11-20 (not attorney certified): ELIGIBILITY / SUBMISSION: Any person may request public information; agencies must make request methods accessible. Identify the responsible agency and use its designated request contact and published process. RESPONSE / PRODUCTION: Under the 2025-amended MCA 2-6-1006, non-local-government public agencies must acknowledge within 5 business days. A single specific clearly identifiable readily available record ordinarily must be provided within 5 working days after acknowledgment, except requests pertaining only to a specified person or property. More complex requests require a time and fee estimate and timely production, potentially within 90 days or 6 months with written explanation; fee-payment and clarification pauses apply. Local governments instead must respond in a timely manner by providing records or an estimate; do not apply the 5-day state-agency acknowledgment rule to local governments. FEES / WAIVERS: Documented charges and estimated prepayment may apply. MCA 2-6-1006(5) generally caps hourly processing rates at $25; complex requests may have a filing fee up to $5 with the first service hour free after payment. Copying and other direct charges may apply; no universal fee waiver was verified. EXEMPTIONS: Constitutional individual privacy can outweigh disclosure. MCA 2-6-1003 allows narrowly tailored safety and security withholding; litigation alone does not justify refusal. Personnel, criminal-investigation and confidential criminal-justice information require record-specific analysis under privacy rules and Title 44, chapter 5, not blanket disclosure or blanket denial. DENIAL / REVIEW: MCA 2-6-1009 requires a written explanation for denial and authorizes a district-court complaint for unlawful denial; failure of a non-local agency to meet statutory response requirements also supports a complaint. A prevailing claimant may be awarded costs and reasonable attorney fees. No universal administrative appeal or filing limitation was verified; check applicable civil procedure and record-specific law promptly. UNRESOLVED: Verify any specialized criminal-justice dissemination procedure, personnel privacy balancing, agency fee policy, and case-specific court limitation before advising a requester.',links:[['Montana Legislature — MCA 2-6-1002 definitions','https://mca.legmt.gov/bills/mca/title_0020/chapter_0060/part_0100/section_0020/0020-0060-0100-0020.html'],['Montana Legislature — MCA 2-6-1003 safety, security and access','https://mca.legmt.gov/bills/mca/title_0020/chapter_0060/part_0100/section_0030/0020-0060-0100-0030.html'],['Montana Legislature — MCA 2-6-1006 deadlines and fees','https://mca.legmt.gov/bills/mca/title_0020/chapter_0060/part_0100/section_0060/0020-0060-0100-0060.html'],['Montana Legislature — MCA 2-6-1009 denial and civil action','https://mca.legmt.gov/bills/mca/title_0020/chapter_0060/part_0100/section_0090/0020-0060-0100-0090.html']]},Massachusetts:{law:'Massachusetts Public Records Law, M.G.L. c. 66, § 10; c. 4, § 7(26); 950 CMR 32.00',summary:'SOURCE-REVIEWED 2026-11-20 (not attorney certified): ELIGIBILITY / SUBMISSION: Any person may request identifiable public records orally or in writing to a custodian or designated Records Access Officer (RAO); written requests by email, mail, hand delivery or fax preserve the ability to appeal. No mandatory agency form. RESPONSE / PRODUCTION: RAO must provide records or a compliant written initial response within 10 business days. If more time is needed, the response must give a reasonable production timeframe; ordinarily no more than 15 business days after receipt for state agencies or 25 business days for municipalities, absent valid extension petition or requester agreement. These are distinct from the 10-day initial-response requirement. FEES / WAIVERS: Electronic copies have no copying fee; ordinary black-and-white copies are capped at $0.05/page. Itemized good-faith estimates are required; labor charges, free hours and waivers differ by agency/municipality and statutory exceptions. Missing the compliant 10-business-day response can waive fees. EXEMPTIONS: c. 4, § 7(26) contains privacy/personnel, investigatory, statutory-confidentiality and other exemptions; police internal-affairs, criminal investigative, medical and body-camera material requires record-specific analysis, not blanket release or withholding. DENIAL: Written denial within 10 business days must identify withheld records and specific exemptions and explain appeal rights. APPEALS: A written request supports appeal to the Supervisor of Records within 90 calendar days of a response, or 90 days from the request if no response; send the petition and full correspondence to Supervisor and copy the RAO. Court relief is also possible under c. 66, § 10A. OPEN: confirm record-specific police body-camera/disciplinary exemptions, special fee exceptions and court litigation deadlines for individual cases. OFFICIAL SOURCES reviewed 2026-11-20: 950 CMR 32.00 official regulation; Secretary initial-response and appeals guidance; c. 66, § 10.',links:[['Massachusetts Secretary — official 950 CMR 32.00 regulation','https://www.sec.state.ma.us/divisions/public-records/download/950-CMR-32-00-Official.pdf'],['Massachusetts Secretary — initial response and timelines','https://www.sec.state.ma.us/divisions/public-records/initial-response-to-a-request-for-public-records.htm'],['Massachusetts Secretary — appealing a denial','https://www.sec.state.ma.us/divisions/public-records/public-records-law/appealing-a-denial.htm'],['Massachusetts Legislature — c. 66 § 10','https://malegislature.gov/Laws/GeneralLaws/PartI/TitleX/Chapter66/Section10'],['Massachusetts Legislature — c. 4 § 7','https://malegislature.gov/Laws/GeneralLaws/PartI/TitleI/Chapter4/Section7']]},Michigan:{law:'Michigan Freedom of Information Act, 1976 PA 442, MCL 15.231–15.246',summary:'PRIMARY-SOURCE AUDIT: 2026-11-20 (Michigan Legislature, MCL through PA 114 of 2026). ELIGIBILITY / REQUEST: Any person other than an incarcerated person excluded by MCL 15.232 may request identifiable existing public-body records; send a written request to the FOIA coordinator, including email. A request must include requester name, mailing address and telephone or email contact under MCL 15.233. Michigan FOIA excludes the judiciary and the governor/executive office under the public-body definition; check the statute for exact scope. RESPONSE, NOT PRODUCTION: Under MCL 15.235 the agency generally must grant, deny, partially grant or issue one extension notice within five business days of legal receipt; a single extension of up to ten business days is permitted. Email is generally deemed received one business day after transmission, with a special spam-folder rule. This is NOT a universal five-day record-delivery deadline. FEES / WAIVERS: MCL 15.234 requires a published fee policy and detailed itemization, limits ordinary letter/legal-size paper copies to ten cents per sheet, limits eligible search/review/redaction labor charges to unreasonably high-cost cases, permits public-interest fee reductions and a first-$20 discount for eligible indigent requesters (subject to conditions). Deposits and fee disputes have separate rules. EXEMPTIONS: MCL 15.243(1)(a) privacy; (b) specified investigative harms; (l) identifiable medical/psychological information; (n) public-safety deployment and codes with public-interest balancing; (s)(ix) law-enforcement personnel records subject to the statutory public-interest balancing test. Do NOT assume all police personnel or investigation records are categorically secret. MCL 15.244 requires separation of nonexempt material. DENIAL / APPEAL: A denial must explain the exemption or nonexistence and review rights. Under MCL 15.240 the requester may appeal to the public-body head (who ordinarily responds within ten business days, with one possible ten-business-day extension), OR sue within 180 days of final denial in circuit court or, for a state public body, Court of Claims. FEE DISPUTE: MCL 15.240a has a distinct 45-day civil-action deadline and conditional administrative fee appeal; verify exact trigger and prerequisites before filing. SPECIAL LAW-ENFORCEMENT RECORDS: Under MCL 15.235(9), a public body hosting another subscribing body’s law-enforcement RMS must identify the subscribing custodian within ten business days; direct the records request to that subscribing body. UNRESOLVED / CASE-SPECIFIC: Verify record-specific statutes, current agency fee policies, body-camera and criminal-history restrictions, and any litigation-related exemptions or deadline tolling with current primary authority. Educational information only, not legal advice.',links:[['Michigan Legislature — FOIA definitions / eligibility','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-232'],['Michigan Legislature — request rights','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-233'],['Michigan Legislature — response / RMS custodian','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-235'],['Michigan Legislature — fees / waivers','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-234'],['Michigan Legislature — exemptions','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-243'],['Michigan Legislature — segregation','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-244'],['Michigan Legislature — denial appeals','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-240'],['Michigan Legislature — fee appeals','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-240a'],['Michigan Attorney General — FOIA guidance','https://www.michigan.gov/ag/resources/foia']]},Minnesota:{law:'Minnesota Government Data Practices Act, Minn. Stat. ch. 13',summary:'PRIMARY-SOURCE REVIEW: 2026-11-20 (Minnesota Revisor 2026 statutes and Minnesota Court of Administrative Hearings). ELIGIBILITY / SUBMISSION: Any person may ask a government entity responsible authority or designee to inspect or copy public government data under § 13.03(3); identify the data and preferred inspection or electronic-copy method. The data-subject access rules under § 13.04(3) differ. RESPONSE / PRODUCTION: § 13.03 requires prompt, appropriate compliance but does not set a universal number of days to acknowledge or produce all public records. A data subject seeking their own public/private data must be accommodated immediately if possible, otherwise within ten days excluding weekends and legal holidays under § 13.04(3). Do not misapply that ten-day period to general public requests. FEES / WAIVERS: Inspection of public data is free; copies may incur actual eligible search/retrieval, reproduction, certification and transmission costs under § 13.03(3), but agencies may not charge for separating public from nonpublic data. Request an itemized justification. No universal fee waiver for copies is established by these provisions; confirm entity-specific policies. EXEMPTIONS: § 13.43(2) makes specified employee information, complaint existence/status and qualifying final disciplinary dispositions public, while § 13.43(4) protects other personnel data; undercover officer data receive special treatment under § 13.43(5). § 13.82 separately classifies law-enforcement response, incident, investigative and related data; do not assume all police reports or investigations are wholly public or wholly exempt. DENIAL: § 13.03(3)(f) requires identification of the specific statutory or federal classification supporting a denial; ask for written certification. REVIEW / DEADLINES: § 13.085 allows a sworn administrative complaint generally within two years of the challenged act, with a discovery exception for concealment/misrepresentation; it requires a $1,000 filing fee or bond, which the Court of Administrative Hearings says cannot be waived. Civil remedies also exist under § 13.08; data-accuracy challenges under § 13.04(4) follow a distinct 60-day appeal rule. UNRESOLVED: Confirm record-specific § 13.82 classifications, body-camera rules, entity fee schedules and applicable civil limitation periods before filing. This is statutory research, not individualized legal advice.',links:[['Minnesota Revisor — § 13.03 access, fees and denial','https://www.revisor.mn.gov/statutes/cite/13.03'],['Minnesota Revisor — § 13.04 data-subject access and correction','https://www.revisor.mn.gov/statutes/cite/13.04'],['Minnesota Revisor — § 13.43 personnel data','https://www.revisor.mn.gov/statutes/cite/13.43'],['Minnesota Revisor — § 13.82 law-enforcement data','https://www.revisor.mn.gov/statutes/cite/13.82'],['Minnesota Revisor — § 13.085 administrative remedy','https://www.revisor.mn.gov/statutes/cite/13.085'],['Minnesota Revisor — § 13.08 civil remedies','https://www.revisor.mn.gov/statutes/cite/13.08'],['Minnesota Court of Administrative Hearings — complaint instructions','https://mn.gov/cah/self-help/administrative-law-overview/data-practices.jsp']]},Indiana:{law:'Indiana Access to Public Records Act, Ind. Code § 5-14-3',summary:'AUDIT CHECKED 2026-11-19. ELIGIBILITY: Any person may request records. SUBMISSION: IC 5-14-3-3 requires reasonable particularity; an agency may require a written form and law-enforcement recordings need special identifiers. RESPONSE: In-person or telephone refusals can become denials within 24 hours; written requests generally require response within seven calendar days. These are acknowledgment/deemed-denial periods, not universal production deadlines; production must be within a reasonable time. FEES: IC 5-14-3-8 generally bars charges for inspection, ordinary search/review and emailed electronic copies, subject to exceptions. 2026 HEA 1360, effective July 1, permits specified security screening and limited nonresident supplemental fees. EXEMPTIONS: IC 5-14-3-4 protects qualifying personnel, confidential and investigative records; recordings have special rules. REVIEW: Written denials identify exemptions and responsible official; Public Access Counselor complaints generally must be filed within 30 days of denial, and court enforcement is separate. OPEN: Check exact codified 2026 amendment and agency fee schedule.',links:[['Indiana Public Access Counselor complaints','https://www.in.gov/pac/formal-complaints'],['Indiana official response and production FAQ','https://faqs.in.gov/hc/en-us/articles/115005226148-How-long-does-the-agency-have-to-give-me-the-records-I-requested'],['Indiana 2026 HEA 1360 agency explanation','https://www.in.gov/inprs/destinationretirement/posts/2026-legislative-updates/'],['Indiana State Board of Accounts APRA statute summary','https://www.in.gov/sboa/library/home/2025-resource-library/2025-state-agencies/'],['Indiana Public Access Counselor handbook','https://www.in.gov/dA/36bbfdc7b4/pac-handbook.pdf?language_id=1']]},Iowa:{law:'Iowa Code Chapter 22',summary:'AUDIT 2026-11-19. ELIGIBILITY: Every person may inspect and copy public records (§22.2). REQUEST: In person, writing, telephone or electronically (§§22.3-22.4); physical presence cannot be required for copy requests. RESPONSE: No universal fixed production deadline. The 20-calendar-day limit (ordinarily 10 business days) in §22.8(4)(d) applies to deciding whether confidential records may be disclosed, not to every request. Open records should be supplied promptly as feasible. FEES: §22.3 limits copying to attributable actual costs, excludes overhead, and generally encourages only copying charges when fulfillment takes less than 30 minutes; communicate estimated reasonable expenses on receipt. EXEMPTIONS: §22.7 protects peace-officer investigative reports, medical and certain personnel records, with qualified disclosure of basic incident facts; §22.15 concerns notice of potentially public employee discipline. REVIEW: §§22.5 and 22.10 permit judicial enforcement; Iowa Public Information Board complaints generally have a strict 60-day period from violation or reasonable discovery (§23.7), with jurisdictional exclusions. OPEN: Other specific confidentiality laws, fee schedules and court-filing limitations require case review. Not legal advice.',links:[['Iowa Legislature 2026 Chapter 22','https://www.legis.iowa.gov/docs/code/2026/22.pdf'],['Iowa Legislature 2026 Chapter 23','https://www.legis.iowa.gov/docs/code/2026/23.pdf'],['Iowa Public Information Board complaint','https://ipib.iowa.gov/ipib-here-assist/file-complaint'],['Iowa Public Information Board timeliness','https://ipib.iowa.gov/production-record'],['Iowa Public Information Board — Chapter 22','https://ipib.iowa.gov/public-records/chapter-22-examination-public-records-open-records'],['Iowa Public Information Board — public records','https://ipib.iowa.gov/public-records']]},Kansas:{law:'Kansas Open Records Act, K.S.A. 45-215 et seq.',summary:'AUDIT 2026-11-19. ELIGIBILITY: Any person may inspect public records (§45-218), subject to exceptions. REQUEST: Identify existing records and follow agency procedures; written requests and identity proof may be required (§45-220). RESPONSE: Act as soon as possible, no later than the end of the third business day (§45-218(d)); a timely explanation of delay does not equal full production. FEES: Reasonable actual-cost staff and copy fees may be assessed under §45-219; agency schedules vary and there is no general mandatory poverty waiver (Attorney General FAQ). EXEMPTIONS: §45-221(a)(4) covers some personnel records but not names, positions, compensation, employment contracts or service length; §45-221(a)(10) covers criminal investigations subject to a conditional judicial disclosure test; §45-221(a)(55) specifically protects captured license-plate data and records concerning automated license-plate recognition system locations. §45-221(d) generally requires separating open material. REVIEW: Request written denial grounds; contact Attorney General or county/district attorney, or pursue district-court relief under §45-222. OPEN: 2026 HB 2134 changes to fee/exemption provisions need effective-text verification, plus case-specific court deadlines. Not legal advice.',links:[['Kansas Legislature 2026 section 45-218','https://www.kslegislature.gov/b2025_26/laws/045_000_0000_chapter/045_002_0000_article/045_002_0018_section/045_002_0018_k/'],['Kansas Legislature 2026 section 45-221','https://www.kslegislature.gov/b2025_26/laws/045_000_0000_chapter/045_002_0000_article/045_002_0021_section/045_002_0021_k/'],['Kansas Legislature 2026 section 45-222','https://www.kslegislature.gov/b2025_26/laws/045_000_0000_chapter/045_002_0000_article/045_002_0022_section/045_002_0022_k/'],['Kansas Attorney General FAQ','https://www.ag.ks.gov/divisions/administration/open-government/kora-faq'],['Kansas Attorney General KORA FAQ','https://www.ag.ks.gov/divisions/administration/open-government/kora-faq'],['Kansas Attorney General resources','https://www.ag.ks.gov/divisions/administration/open-government/resources']]},Kentucky:{law:'Kentucky Open Records Act, KRS 61.870–61.884',summary:'AUDIT CHECKED 2026-11-19 (Kentucky Attorney General 26-ORD-216, KRS 61.870–61.884, 40 KAR 1:030). ELIGIBILITY: KRS 61.870(10) defines Kentucky resident broadly, including residents, Kentucky workers and property owners, qualifying businesses, authorized representatives, and defined news organizations; do not treat physical domicile as the sole qualification. REQUEST: Send a written request identifying existing records to the official custodian by permitted means. KRS 61.872(2)(c) prohibits requiring a particular request form; Kentucky AG decision 26-ORD-216 confirms this. RESPONSE: Under KRS 61.880(1), written grant/denial determination is due within five business days excluding weekends and legal holidays, not necessarily complete production. Under KRS 61.872(5), delay when records are in use, storage, or otherwise unavailable requires a detailed explanation and earliest availability date. FEES: KRS 61.874 regulates reasonable copying charges and commercial use; inspect the custodian schedule and statutory limits. EXEMPTIONS: KRS 61.878 includes privacy, confidential personnel-related information and law-enforcement investigative material when statutory criteria are met; criminal-history records may also implicate KRS 17.150. REVIEW: A written denial or improper delay/fees may be taken to the Kentucky Attorney General under KRS 61.880; an AG decision can be appealed in circuit court within 30 days. KRS 61.882 also governs judicial enforcement. OPEN: Verify specific fee rates and record-category exemptions for the target custodian; no universal production deadline should be promised.',links:[['Kentucky AG — 2026 decision on residency, forms and appeals','https://www.ag.ky.gov/Resources/orom/2026/26-ORD-216.pdf'],['Kentucky legislature — AG appeal regulation 40 KAR 1:030','https://apps.legislature.ky.gov/law/kar/titles/040/001/030/'],['Kentucky AG — 2026 delay decision','https://www.ag.ky.gov/Resources/orom/2026/26-ORD-137.pdf'],['Kentucky Attorney General — Open Records and Open Meetings','https://www.ag.ky.gov/Resources/orom/Pages/default.aspx'],['Kentucky Attorney General — request instructions','https://www.ag.ky.gov/Contact-Us/Pages/Open-Records-Requests.aspx']]},Louisiana:{law:'Louisiana Public Records Law, La. R.S. 44:1 et seq.',summary:'AUDIT CHECKED 2026-11-19 (Louisiana Legislative Auditor Public Records Law FAQ revised August 2026; La. R.S. 44:1–44:42). ELIGIBILITY: Under R.S. 44:31, adults may inspect and copy records and any person may obtain copies, subject to restrictions in R.S. 44:31.1 for certain convicted prisoners; requests to the Governor’s office are subject to a Louisiana residency restriction. REQUEST: Direct a reasonably described request to the records custodian; in-person, written and electronic requests may be used. R.S. 44:33.1 requires public custodian contact information. RESPONSE: R.S. 44:33 generally requires immediate access to an available, nonexempt record; when a record is in active use, written certification must give a date and hour within three business days. R.S. 44:32 requires written explanation citing legal authority when withheld; under R.S. 44:35, five business days without a written determination or reasonable time estimate can trigger court remedies. Five days is NOT a universal production deadline. FEES: Inspection during regular hours generally is free; copies may be charged under a published reasonable local schedule or state uniform schedule. Discretionary reductions or waivers may apply for indigent residents or public-purpose use. EXEMPTIONS: R.S. 44:3 governs certain criminal investigative records; R.S. 44:11 protects specified public employee personal and medical data; R.S. 44:4.1 incorporates other confidentiality provisions. REVIEW: R.S. 44:35 permits mandamus, injunctive or declaratory relief in the district court of the parish where the custodian’s office is located; fees, damages and penalties are fact-dependent. OPEN: Confirm specialized law-enforcement record exemptions and exact agency copy fee schedule before requesting.',links:[['Louisiana Legislative Auditor — Public Records Law FAQ revised August 2026','https://app.lla.state.la.us/llala.nsf/7C469838E7BC1C5186257AC2004F6279/$FILE/Public%20Records%20Law%20FAQ.pdf'],['Louisiana Legislative Auditor — records request guidance','https://www.lla.la.gov/public-records-request'],['Louisiana Legislature — R.S. 44:31','https://legis.la.gov/Legis/LawPrint.aspx?d=99688'],['Louisiana Legislature — R.S. 44:31.1','https://www.legis.la.gov/Legis/LawPrint.aspx?d=99689']]},Florida:{law:'Florida Constitution Art. I § 24; Florida Statutes Chapter 119',summary:'ELIGIBILITY: Any person may request nonexempt Florida state, county and municipal records under Fla. Const. art. I, § 24 and Fla. Stat. § 119.01. SUBMISSION: Request existing records from the agency custodian; identify the records and retain a dated copy. RESPONSE: § 119.07(1) requires inspection and copying at reasonable times under reasonable conditions, with reasonable time for retrieval and redaction; there is no universal fixed five- or ten-day production deadline. FEES: § 119.07(4) generally allows actual duplication costs or specified statutory copy charges; extensive clerical or supervisory assistance or extensive information technology use can justify a special service charge based on actual costs. EXEMPTIONS: § 119.071 includes active criminal investigative and intelligence information and specified law-enforcement personnel privacy and safety protections; segregate nonexempt portions under § 119.07(1)(d). DENIAL: § 119.07(1)(e) requires the custodian to state the basis for an exemption, citing the statute if requested. REVIEW: Judicial enforcement under §§ 119.11–119.12; attorney-fee awards generally require written notice identifying the request at least five business days before suit, with a posted-contact-information exception; no automatic damages under § 119.12. SOURCE AUDIT 2026-11-19: 2026 Florida Legislature Chapter 119 and § 119.12 checked. OPEN: Agency-specific exemptions, service-fee calculations and any case-specific filing limits require separate confirmation.',links:[['Florida Legislature — 2026 Chapter 119','https://www.leg.state.fl.us/Statutes/index.cfm?App_mode=Display_Statute&URL=0100-0199/0119/0119.html'],['Florida Legislature — § 119.12 attorney fees','https://www.leg.state.fl.us/Statutes/index.cfm?App_mode=Display_Statute&URL=0100-0199/0119/Sections/0119.12.html'],['Florida Attorney General Sunshine Manual','https://www.myfloridalegal.com/sites/default/files/government-in-the-sunshine-manual.pdf']]},Georgia:{law:'Georgia Open Records Act, O.C.G.A. §§ 50-18-70 et seq.',summary:'ELIGIBILITY: Georgia Open Records Act, O.C.G.A. §§ 50-18-70–77, generally permits requests for nonexempt agency records, including records held by private contractors acting for public agencies. SUBMISSION: Ask the designated custodian; oral requests may be accepted, but written requests are needed for judicial enforcement, so preserve the date and wording. RESPONSE: Under §§ 50-18-71 and 50-18-72(h), agencies generally produce records within three business days unless exceptional circumstances prevent production; if delayed, provide a written timetable, cost estimate and specific statutory withholding basis within that period. FEES: § 50-18-71 allows reasonable direct search, retrieval and redaction labor costs capped by the lowest-paid qualified full-time employee; first 15 minutes free; ordinary paper copies generally capped at 25 cents per page. Prepayment is limited by statutory conditions, including estimates over $500 or certain prior unpaid charges. EXEMPTIONS: § 50-18-72 covers pending investigations and specified personal information; redact protected material rather than withhold an entire otherwise releasable record. REVIEW: Attorney General open-government complaint or mediation may help; court enforcement is available under § 50-18-73. Do not apply Open Meetings Act litigation deadlines to Open Records Act requests. SOURCE AUDIT 2026-11-19: Georgia Attorney General request guidance, official FAQ and published legal interpretations checked. OPEN: Exact limitations period for particular court claims and changes to police-record exceptions need independent confirmation.',links:[['Georgia Attorney General — open government FAQ','https://law.georgia.gov/key-issues/open-government/faq-open-government'],['Georgia Attorney General — how to request','https://law.georgia.gov/key-issues/open-government/how-make-open-records-request'],['Georgia Attorney General — law enforcement investigation opinion','https://law.georgia.gov/opinions/97-20'],['Georgia Attorney General — how to request','https://law.georgia.gov/key-issues/open-government/how-make-open-records-request'],['Georgia Governor — records overview','https://gov.georgia.gov/contact-us/open-records-request']]},Hawaii:{law:'Uniform Information Practices Act (Modified), Hawaii Revised Statutes Chapter 92F',summary:'AUDIT 2026-11-19: Any person may request records under HRS chapter 92F. Send a written formal request to the holding agency with contact information and records description. HAR 2-71-13: fully public records generally disclosed within 10 business days; partially exempt records receive notice within 10 business days and public portions within 5 business days after notice or required prepayment. Extenuating circumstances allow acknowledgment within 10 days and notice by 20 business days. HAR 2-71-31 generally charges $2.50 per 15 minutes search and $5 per 15 minutes review, first $30 waived; alternative $60 public-interest waiver requires qualifying dissemination facts. Copying costs separate. HRS 92F-13 protects privacy and other confidential information, including record-specific public-safety exceptions. Written OIP denial appeal generally due within one year under HAR 2-73; court review under HRS 92F-15 does not require OIP exhaustion. SOURCES: https://ags.hawaii.gov/oip/uipa-rules/ ; https://ags.hawaii.gov/oip/guide-to-oip-appeals/ ; https://ags.hawaii.gov/oip/how-to-request-a-record/ . OPEN: Proposed 2026 fee-rule changes are not yet treated as effective; monitor https://ags.hawaii.gov/oip/news-from-oip-oip-to-hold-public-hearing-on-proposed-new-administrative-rules/ .',links:[['Hawaii Office of Information Practices — UIPA','https://ags.hawaii.gov/oip/uipa-/'],['Hawaii agency — submitting a UIPA request','https://budget.hawaii.gov/contact/uniform-information-practices-act/']]},Idaho:{law:'Idaho Public Records Act, Idaho Code Title 74, Chapter 1',summary:'AUDIT 2026-11-19: Idaho Code Title 74 ch. 1 allows residents and nonresidents to request existing public records from designated custodians; label the submission a public-records request under § 74-103. Resident requests generally receive grant/denial within 3 working days and, with written delay notice, production within 10 working days. Nonresident requests by persons not employed by residents generally have 21 days for grant/denial and up to 35 days for production after notice; electronic conversion can alter timing. § 74-102 generally provides Idaho residents the first two processing hours and 100 pages without charge, subject to statutory conditions; additional permissible labor and copying charges apply. §§ 74-104 through 74-111 contain law-enforcement, personnel, medical and privacy exemptions requiring record-specific review. Written denial must cite law and remedies. § 74-115 generally permits a district-court petition within 180 days after denial mailing; no mandatory internal appeal exhaustion. SOURCES: Idaho AG 2026 manual https://www.ag.idaho.gov/content/uploads/2026/07/PublicRecordsLaw.pdf ; AG guidance https://www.ag.idaho.gov/office-resources/public-records/ ; agency procedures https://adm.idaho.gov/public-record-request/ . OPEN: Check agency-specific fee schedules and particular record exceptions.',links:[['Idaho Attorney General — public records','https://www.ag.idaho.gov/office-resources/public-records/'],['Idaho Attorney General — 2026 manual','https://www.ag.idaho.gov/content/uploads/2026/07/PublicRecordsLaw.pdf']]},Illinois:{law:'Illinois Freedom of Information Act, 5 ILCS 140',summary:'AUDIT CHECKED 2026-11-19. ELIGIBILITY: Any person can request existing public records. SUBMISSION: Send an identifiable request to the public body FOIA officer; an agency cannot mandate its own form or a reason except for commercial use or fee-waiver decisions (5 ILCS 140/3). RESPONSE: Ordinary noncommercial requests generally require compliance or denial within five business days; an enumerated reason permits a written five-business-day extension. Commercial, recurrent and voluminous requests differ. FEES: Section 6 generally makes the first 50 standard black-and-white pages free and limits further pages to $0.15 each; ordinary search/review labor is not chargeable, subject to special categories. EXEMPTIONS: Sections 7 and 7.5 protect qualifying privacy, investigative and other confidential records, including special body-camera protections; redact and release segregable nonexempt material. REVIEW: Section 9.5 generally provides 60 days for PAC review after final denial; section 11 provides judicial enforcement. OPEN: Check body-camera disclosure exceptions and judicial deadlines for specific cases.',links:[['Illinois Legislature section 3 request and response','https://www.ilga.gov/legislation/ilcs/fulltext?DocName=000501400K3'],['Illinois Legislature section 6 fees','https://www.ilga.gov/legislation/ilcs/fulltext?DocName=000501400K6'],['Illinois Legislature section 7.5 exemptions','https://www.ilga.gov/legislation/ilcs/fulltext?DocName=000501400K7.5'],['Illinois Attorney General PAC guide','https://illinoisattorneygeneral.gov/Page-Attachments/FOIAPAC/PACGuide.pdf'],['Illinois Attorney General — Public Access Counselor','https://illinoisattorneygeneral.gov/open-and-honest-government/pac/'],['Illinois General Assembly — FOIA review provision','https://www.ilga.gov/documents/legislation/ilcs/documents/000501400K9.5.htm']]},Arkansas:{law:'Arkansas Freedom of Information Act, Ark. Code Ann. §§ 25-19-101 et seq.',summary:'ELIGIBILITY: Arkansas FOIA access to public records is generally for Arkansas citizens, subject to statutory interpretation and exceptions. SUBMISSION: Direct a sufficiently specific request to the records custodian; oral, email, telephone and written requests may be accepted. RESPONSE: Records are generally available immediately unless in active use or storage, when they should generally be made available within three working days. Special 24-hour decision provisions apply to personnel and employee-evaluation records. FEES: The custodian generally may charge actual reproduction costs plus mailing, not a general search fee. EXEMPTIONS: Personnel, employee evaluations, undisclosed law-enforcement investigations and other protected information have specific statutory treatment. REVIEW: Judicial enforcement is available under the FOIA; check standing, notice and procedural requirements before litigation. AUDIT: Arkansas Attorney General 21st-edition FOIA handbook and official AG overview checked November 18, 2026.',links:[['Arkansas Attorney General FOIA overview','https://arkansasag.gov/divisions/opinions-foia/arkansas-freedom-of-information-act/'],['Arkansas FOIA handbook (2025)','https://healthy.arkansas.gov/wp-content/uploads/2025-FOIA-Handbook-21st-Edition-ver4.pdf']]},California:{law:'California Public Records Act, Cal. Gov. Code §§ 7920.000–7930.215',summary:'ELIGIBILITY: Any person may request disclosable state or local agency records under the California Public Records Act, Gov. Code § 7920.000 et seq. SUBMISSION: Identify records and send a request to the agency holding them; agencies generally must assist in identifying responsive records. RESPONSE: § 7922.535 requires an initial determination, not necessarily completed production, within the statutory period; the previously codified rule was ten calendar days with a possible 14-calendar-day unusual-circumstances extension. IMPORTANT CURRENT-LAW ALERT: 2026 legislative materials for AB 1821 describe a change to ten BUSINESS days and a 14-business-day extension; verify enactment and operative date directly before calculating a deadline. FEES: Ordinary copies generally involve direct duplication costs under § 7922.530, with additional rules for electronic extraction. EXEMPTIONS: § 7922.000 and specific law-enforcement, personnel, privacy and other exemptions can apply. REVIEW: Denial may be challenged through court proceedings under the CPRA; confirm current statutory remedy provisions. AUDIT STATUS: Primary statute and 2026 legislative change identified; operative-date verification remains OPEN.',links:[['California DOJ public records guidance','https://oag.ca.gov/consumers/general/pra'],['California DOJ PRA FAQ','https://oag.ca.gov/consumers/general/pra_faq'],['California DOJ guidelines PDF','https://oag.ca.gov/system/files/media/pra-guidelines.pdf']]},Colorado:{law:'Colorado Open Records Act, C.R.S. §§ 24-72-201–206',summary:'ELIGIBILITY/SUBMISSION: Colorado Open Records Act (CORA), C.R.S. §§ 24-72-201 et seq., generally covers public records, but criminal justice records may instead fall under the Colorado Criminal Justice Records Act (CCJRA). Send an identifiable request to the custodian following the agency’s submission rules. RESPONSE: Under § 24-72-203(3)(b), records not readily available are presumptively available within three working days; qualifying extenuating circumstances can add up to seven working days with timely written notice. FEES: Research, retrieval and copying fees are governed by § 24-72-205 and published agency schedules; the first hour of research and retrieval is generally free. EXEMPTIONS: Statutory confidential, privileged, personnel and criminal-justice information may be excluded or governed by CCJRA. REVIEW: Request a written basis for denial; CORA enforcement procedures are set out in § 24-72-204(5), with prerequisites and timing that must be checked before filing. AUDIT: Colorado Attorney General CORA/CCJRA guidance, Department of Revenue guidance and § 24-72-203 checked November 18, 2026.',links:[['Colorado Department of Revenue CORA guidance','https://cdor.colorado.gov/cora'],['Colorado Attorney General CORA and CCJRA','https://coag.gov/media-center/colorado-open-records-act-cora/'],['Colorado legislative CORA summary','https://content.leg.colorado.gov/sites/default/files/colorado-open-records-act-cora-colorado-law-summary-accessible.pdf']]},Connecticut:{law:'Connecticut Freedom of Information Act, Conn. Gen. Stat. §§ 1-200 et seq.',summary:'ELIGIBILITY: Every person may inspect public agency records under Conn. Gen. Stat. § 1-210(a), subject to statutory exemptions. SUBMISSION: Request existing records from the agency holding them; the FOI Commission explains that an agency may require a written request for copies but not simply to inspect. RESPONSE: Records must be available promptly; § 1-206(a) generally requires written denial within four business days, with a ten-business-day exception for certain § 1-214 personnel-related requests. Noncompliance within the applicable period is deemed a denial; these are NOT universal production deadlines. FEES: Under § 1-212, ordinary state-agency copies generally cost no more than $0.25 per page and municipal copies $0.50 per page, with statutory exceptions and electronic-media rules. EXEMPTIONS: § 1-210(b) includes specified law-enforcement, privacy, personnel and other exceptions; § 1-214 imposes special employee-notice rules in some cases. APPEAL: § 1-206(b)(1) generally requires a written complaint to the Freedom of Information Commission within 30 days after denial; confirm deemed-denial accrual and any special circumstances. PRIMARY SOURCES CHECKED 2026-11-19: Connecticut General Assembly 2026 supplement to Chapter 14; Connecticut FOI Commission guidance and FOI Act. OPEN: Agency-specific copying formats and record-specific exemptions must be verified.',links:[['Connecticut General Assembly Chapter 14','https://www.cga.ct.gov/current/pub/chap_014.htm'],['Connecticut 2026 statutory supplement','https://www.cga.ct.gov/2026/sup/chap_014.htm'],['Connecticut Freedom of Information Commission','https://portal.ct.gov/FOI/'],['Connecticut FOI Commission — appeal and fee guidance','https://portal.ct.gov/FOI/Common-Elements/Template-V4/How-Do-I_B']]},Delaware:{law:'Delaware Freedom of Information Act, 29 Del. C. §§ 10001–10008',summary:'ELIGIBILITY: Delaware FOIA § 10003 uses citizen access language; nonresident eligibility and case law should be checked before relying on the statute for a particular requester. SUBMISSION: Under § 10003(f), send a written request to the public body by email, mail, fax, in person or online; the standardized form is optional, and records must be described sufficiently for a reasonable search. RESPONSE: § 10003(h) requires an answer as soon as possible and within 15 business days, either access, reasoned denial or a permitted extension with a good-faith estimate for voluminous records, legal review or archived/stored records. This is not a guaranteed production deadline. FEES: § 10003(m) generally provides the first 20 standard black-and-white pages free, then $0.10 per sheet; administrative fees apply only after the first hour and require an itemized estimate, with other statutory/local-code rules possible. EXEMPTIONS: § 10002 excludes specified investigative, personnel, medical, pending-litigation and other protected records. APPEAL: Under § 10005(b), records-denial lawsuits generally have a 60-day deadline; for state bodies the Attorney General is obligated to represent, a petition to the Chief Deputy within 60 days is mandatory before specified Superior Court review, with a further 60-day appeal period after AG decision. Other AG petitions and remedies differ. PRIMARY SOURCES CHECKED 2026-11-19: Delaware Code Chapter 100 §§ 10002, 10003, 10005; Delaware DOJ Open Government guidance and March 10, 2026 FOIA opinion. OPEN: Apply the correct agency type and jurisdiction to appeal route; specific exemptions and local fees require record-specific review.',links:[['Delaware Code — current FOIA chapter','https://delcode.delaware.gov/title29/c100/'],['Delaware statewide FOIA portal','https://delaware.gov/freedom-of-information-act/'],['Delaware Department of Justice open government','https://attorneygeneral.delaware.gov/executive/open-government/']]},Alaska:{law:'Alaska Statutes §§ 40.25.110–40.25.125',summary:'ELIGIBILITY: Alaska’s Public Records Act covers state and local agencies, but executive-branch regulations do not automatically govern all municipalities, the legislature or courts. SUBMISSION: Make a clear request to the custodian, identifying existing records; electronic-services requests may have separate rules under AS 40.25.115. RESPONSE: For executive-branch requests under AS 40.25.110, 2 AAC 96.325 generally allows an initial 10-working-day response and a 10-working-day extension, with additional extensions possible by agreement or Attorney General approval; response is not always complete production. FEES: Recoverable search and copying charges may require prepayment under 2 AAC 96.360; public-interest fee relief is addressed in 2 AAC 96.370. EXEMPTIONS: Statutory confidential information and protected records are excluded; agencies generally need not create new records. APPEAL: Under 2 AAC 96.340, an executive-branch administrative denial appeal generally must be mailed or hand-delivered to the agency head within 60 working days. AUDIT: Alaska Department of Law APRA guidance and executive-branch regulations reviewed November 18, 2026.',links:[['Alaska Department of Law — APRA guide','https://law.alaska.gov/doclibrary/APRA.html'],['Alaska Legislature — statutes','https://www.akleg.gov/basis/statutes.asp#40.25.110']]},Arizona:{law:'Arizona Revised Statutes §§ 39-121–39-121.03',summary:'ELIGIBILITY: Any person may inspect public records under A.R.S. § 39-121. SUBMISSION: Direct a reasonably specific request to the officer or agency holding the records; noncommercial requests generally need not be written, but document a denial in writing. RESPONSE: Records must be furnished promptly; Arizona has no universal fixed numerical response deadline, and failure to respond promptly may be treated as a denial under § 39-121.01(E). FEES: Inspection and copies differ; reasonable copy fees may apply, and § 39-121.03 imposes additional rules for commercial use. EXEMPTIONS: Confidentiality statutes, privacy, public-safety and other recognized interests may justify withholding; some law-enforcement and victim records have specific protections. REVIEW: § 39-121.02(A) allows a denied requester to seek a special action in superior court without a required administrative appeal; § 39-121.02(B) addresses possible attorney fees and costs for substantially prevailing requesters. AUDIT: Arizona Legislature §§ 39-121–39-121.03 and Ombudsman guidance reviewed November 18, 2026.',links:[['Arizona Legislature — Title 39','https://www.azleg.gov/arsDetail/?title=39'],['Arizona Ombudsman — public records law','https://www.azoca.gov/arizona-public-records-law/'],['Arizona Ombudsman — public records FAQ','https://www.azoca.gov/faqs/faqs-public-access-laws/']]},Alabama:{law:'Alabama Code § 36-12-40 and §§ 36-12-43 through 36-12-45',summary:'ELIGIBILITY: Alabama’s public-records law generally grants access to Alabama residents; an officer may require reasonable proof of residency and may elect to respond to nonresidents. SUBMISSION: Identify records with reasonable specificity; the officer may require its published form or written procedure. RESPONSE: Under § 36-12-44, a proper standard request must be acknowledged within 10 business days and substantively fulfilled or denied within 15 business days after acknowledgment, subject to written 15-business-day extensions and statutory tolling. Time-intensive requests have different fee and 45-business-day procedures. FEES: Reasonable fees and prepayment may be required; inspect the particular agency’s published schedule. EXEMPTIONS: Privileged, confidential and other legally protected records may be withheld; the statute does not require creation of new records. DENIAL/REMEDY: § 36-12-44 establishes conditional presumptions of denial, including 30-business-day/60-calendar-day thresholds for standard requests; court enforcement and applicable limitations should be independently checked before filing. AUDIT: Primary source § 36-12-44 and Alabama Secretary of State procedures reviewed November 18, 2026.',links:[['Official statute § 36-12-40','https://alison.legislature.state.al.us/code-of-alabama?section=36-12-40'],['Official request procedures § 36-12-44','https://alison.legislature.state.al.us/code-of-alabama?section=36-12-44'],['Alabama Secretary of State request instructions','https://www.sos.alabama.gov/public-records-request']]}};
 const verifiedPanel=document.createElement('section');verifiedPanel.className='card';verifiedPanel.id='verified-state';verifiedPanel.setAttribute('aria-label','State public records research and source links');panel.insertBefore(verifiedPanel,draft.previousElementSibling);
 function showVerified(name){verifiedPanel.replaceChildren();const info=verified[name];if(!info){verifiedPanel.hidden=true;return;}verifiedPanel.hidden=false;const title=document.createElement('h3');title.textContent='State public-records law: '+info.law;verifiedPanel.appendChild(title);const p=document.createElement('p');p.textContent=info.summary;verifiedPanel.appendChild(p);for(const [label,url] of info.links){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label;a.style.display='block';a.style.marginBottom='8px';verifiedPanel.appendChild(a);}const disclaimer=document.createElement('p');disclaimer.textContent=independentlyAuditedStates.has(name)?'Primary-source statutory audit completed 2026-11-19 for the listed sections. Agency rules and record-specific exceptions may still affect outcomes.':enhancedReviewStates.has(name)?'Expanded procedural research, not independently audited for every exception or deadline. Confirm current primary sources before relying on a rule.':'Preliminary research. Fees, exemptions, appeal routes and deadlines still require source-by-source verification. Not attorney-reviewed legal advice.';verifiedPanel.appendChild(disclaimer);const detail=document.createElement('a');detail.href='https://www.rcfp.org/open-government-guide/'+name.toLowerCase().replace(/\s+/g,'-')+'/';detail.target='_blank';detail.rel='noopener noreferrer';detail.textContent='Read the detailed '+name+' open-records guide (eligibility, exemptions, fees and appeals)';detail.style.display='block';verifiedPanel.appendChild(detail);}

 const slug=name=>name.toLowerCase().replace(/\s+/g,'-');
 const sources='Review the state-specific Reporters Committee guide linked below, then verify current requirements against official statutes and the receiving agency’s instructions.';
 function template(name){return 'PUBLIC RECORDS REQUEST — '+name.toUpperCase()+' (GENERAL STARTING DRAFT; NOT LEGALLY REVIEWED)\n\nDate: [DATE]\nTo: [PUBLIC AGENCY / RECORDS CUSTODIAN]\nAgency address or approved request channel: [ADDRESS / PORTAL]\n\nSubject: Request for access to public records\n\nHello,\n\nI request access to the following identifiable public records maintained by your agency, to the extent disclosure is authorized by applicable '+name+' law:\n\n[DESCRIBE SPECIFIC RECORDS, APPROXIMATE DATES, OFFICES, AND SEARCH TERMS]\n\nPlease let me know whether the records are available electronically and whether any fees apply before processing if the cost will exceed [AMOUNT]. If any responsive material is withheld, please identify the applicable legal basis and provide any reasonably segregable disclosable portions where required by law.\n\nPlease advise me of any agency-specific submission requirements. I understand that requester eligibility, response periods, exemptions, fees and review rights vary and must be independently verified.\n\nThank you,\n[REQUESTER NAME IF REQUIRED]\n[REPLY CONTACT / DELIVERY METHOD]\n\nIMPORTANT: Verify '+name+' requester eligibility, public-records statute, exemptions, response periods and agency rules before sending. Do not request or disclose restricted personnel, criminal justice, medical, privileged or confidential information without authorization.';}
 state.addEventListener('change',()=>{const name=state.value;if(!name){note.textContent='Choose a state to see resource availability.';panel.hidden=true;return;}panel.hidden=false;showVerified(name);if(guideLink){guideLink.href=rcfp+slug(name)+'/';guideLink.textContent=name+' open-government guide (RCFP)';}heading.textContent=name+' — public-records starting resources';intro.textContent=name==='Michigan'?'Michigan: the separate Michigan FOIA Desk offers a locally generated draft. The general template below is also available. '+sources:'Use the resources below to locate '+name+' public-records law, then adapt the free blank request letter. '+sources;note.textContent='Showing '+name+' resources below. Any state summary is preliminary research, not comprehensive legal verification. Check current official sources and deadlines.';draft.textContent=template(name);panel.scrollIntoView({behavior:'smooth',block:'start'});});
 download.addEventListener('click',()=>{if(!state.value)return;const blob=new Blob([draft.textContent],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='the-shield-'+state.value.toLowerCase().replace(/\s+/g,'-')+'-public-records-request.txt';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);});
 print.addEventListener('click',()=>{if(!state.value)return;const w=window.open('','_blank');if(!w){note.textContent='Pop-up blocked. Use the download button and print the saved text file.';return;}const pre=w.document.createElement('pre');pre.style.whiteSpace='pre-wrap';pre.style.overflowWrap='anywhere';pre.style.wordBreak='break-word';pre.style.fontFamily='serif';pre.style.fontSize='11pt';pre.style.lineHeight='1.45';pre.style.maxWidth='100%';pre.style.margin='0';w.document.body.style.margin='0';w.document.body.style.padding='0.5in';w.document.body.style.boxSizing='border-box';pre.textContent=draft.textContent;w.document.body.appendChild(pre);w.document.title='THE SHIELD — '+state.value+' blank public records request';w.print();});
})();
